window.DB[8]=[{"id":"c08p1","page":94,"title":"POINT 1","sub":"동사 병렬","prompt":"and / but / or를 누르세요","pnote":{"t":"동사는 동사끼리 잇는다","lines":["and / but / or 앞뒤는 같은 모양끼리 → 동사 + 동사","앞 동사의 시제·수에 맞추고 -ing·to는 이을 수 없다"]},"items":[{"no":"예제","chunks":[{"en":"You can start working a month earlier","ko":"당신은 한 달 일찍 일하기를 시작할 수 있다","k":"S","lab":"S 짝 A start (동사원형)","h":[["start","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"receive a larger bonus for doing so.","ko":"그렇게 함으로써 더 큰 보너스를 받을 수 있다.","k":"V","lab":"V receive (receiving 아님)"}],"tr":"당신은 한 달 일찍 일하는 것을 시작하고 그렇게 하는 것에 대해 더 큰 보너스를 받을 수 있다.","why":"조동사 <b>can</b> 뒤에 동사원형 <b>start</b>(start: 시작하다)가 있고, and가 이 start와 짝이 될 동사를 이어 줘요. 그래서 동사원형 <b>receive</b>(receive: 받다)가 맞아요. receiving은 동사가 아니라 준동사라서 start와 짝이 될 수 없어요.","ex":"<b>working a month earlier</b>의 working은 start 뒤에 온 목적어(~하는 것)예요. receive의 짝은 working이 아니라 start예요. 이렇게 <b>무엇과 무엇이 짝인지</b> 덩어리를 가려내는 게 중요해요. <b>for doing so</b>는 &ldquo;그렇게 하는 것에 대해&rdquo;.","st":[["s","짝 A","start"],["c","접속사","and"],["s","짝 B","receive (동사원형)"]],"verb":{"ok":"receive","no":"receiving"},"note":{"t":"앞 동사와 같은 모양으로 맞추기","lines":["start and → receive","and 앞이 동사 start → 뒤도 동사원형 receive (-ing 아님)"]}},{"no":"1","chunks":[{"en":"I could see the fireworks","ko":"나는 불꽃놀이를 볼 수 있었다","k":"S","lab":"S 짝 A see (동사원형)","h":[["see","s"]]},{"en":"from the roof of my building","ko":"내 건물 지붕에서","k":"","lab":""},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"take pictures of them.","ko":"그것들의 사진을 찍을 수 있었다.","k":"V","lab":"V take (taking 아님)"}],"tr":"나는 내 건물 지붕에서 불꽃놀이를 보고 사진을 찍을 수 있었다.","why":"<b>could</b> 뒤에 동사원형 <b>see</b>(see: 보다)가 있고, and 뒤의 동사도 같은 could에 이어져요. 그래서 동사원형 <b>take</b>(take: (사진을) 찍다)가 맞아요. taking은 준동사라서 동사 see와 짝이 될 수 없어요.","ex":"<b>take pictures</b>는 &ldquo;사진을 찍다&rdquo;예요. pictures of them의 them은 fireworks(불꽃놀이)를 가리켜요.","st":[["s","짝 A","see"],["c","접속사","and"],["s","짝 B","take (동사원형)"]],"verb":{"ok":"take","no":"taking"},"note":{"t":"앞 동사와 같은 모양으로 맞추기","lines":["see and → take","and 앞이 동사 see → 뒤도 동사원형 take"]}},{"no":"2","chunks":[{"en":"After an important exam,","ko":"중요한 시험 후에,","k":"","lab":""},{"en":"Tim usually either gets some rest","ko":"팀은 보통 휴식을 취한다","k":"S","lab":"S 짝 A gets (단수동사)","h":[["gets","s"]]},{"en":"or","ko":"또는","k":"C","lab":"C 접속사 either ~ or"},{"en":"goes downtown to meet his friends.","ko":"친구들을 만나러 시내에 간다.","k":"V","lab":"V goes (go 아님)"}],"tr":"중요한 시험 후에, Tim은 보통 휴식을 취하거나 친구들을 만나러 시내에 간다.","why":"<b>either A or B</b>(A와 B 둘 중 하나)에서 A는 <b>gets</b>(get: 취하다)예요. 주어 Tim은 한 명이라서 동사에 -s가 붙은 단수동사예요. 그래서 B도 단수동사 <b>goes</b>(go: 가다)로 맞춰요.","ex":"<b>to meet his friends</b>는 &ldquo;친구들을 만나러&rdquo;(목적)라는 뜻이에요. downtown은 &ldquo;시내에&rdquo;.","st":[["s","짝 A","gets (단수동사)"],["c","접속사","either ~ or"],["s","짝 B","goes (단수동사)"]],"verb":{"ok":"goes","no":"go"},"note":{"t":"앞 동사의 수에 맞추기","lines":["gets or → goes","앞 동사 gets가 단수동사 → 뒤도 단수동사 goes"]}},{"no":"3","chunks":[{"en":"The groups of workers accepted the new policy,","ko":"노동자 집단들은 새 정책을 받아들이고,","k":"S","lab":"S 짝 A accepted (과거)","h":[["accepted","s"]]},{"en":"asked the company to change it,","ko":"회사에 그것을 바꾸라고 요청하고,","k":"S","lab":"S 짝 B asked (과거)","h":[["asked","s"]]},{"en":"or","ko":"또는","k":"C","lab":"C 접속사"},{"en":"refused it.","ko":"그것을 거부했다.","k":"V","lab":"V refused (refuse 아님)"}],"tr":"노동자 집단들은 새 정책을 받아들이거나, 회사에 그것을 바꾸라고 요청하거나, 그것을 거부했다.","why":"<b>accepted</b>(accept: 받아들이다)와 <b>asked</b>(ask: 요청하다)가 둘 다 과거 동사예요. or 뒤에도 과거 동사 <b>refused</b>(refuse: 거부하다)로 시제를 맞춰요. 세 개를 나열할 때는 마지막 앞에 and / or를 써요.","ex":"<b>ask A to V</b>는 &ldquo;A에게 V하라고 요청하다&rdquo;예요. asked the company to change it = 회사에 그것을 바꾸라고 요청했다.","st":[["s","짝 A","accepted (과거)"],["s","짝 B","asked (과거)"],["c","접속사","or"],["s","짝 C","refused (과거)"]],"verb":{"ok":"refused","no":"refuse"},"note":{"t":"앞 동사의 시제에 맞추기","lines":["accepted, asked or → refused","앞 동사들이 모두 과거 → 뒤도 과거 refused"]}},{"no":"4","chunks":[{"en":"Brown lines run along the backs","ko":"갈색 선들이 등을 따라 이어지고","k":"S","lab":"S 짝 A run (복수 동사)","h":[["run","s"]]},{"en":"of the amazing lizards","ko":"그 놀라운 도마뱀들의","k":"","lab":""},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"continue down their tails.","ko":"꼬리 아래로 계속 이어진다.","k":"V","lab":"V continue (continuing 아님)"}],"tr":"갈색 선들이 그 놀라운 도마뱀들의 등을 따라 이어지고, 꼬리로 계속 내려간다.","why":"주어 <b>Brown lines</b>(복수)의 동사는 <b>run</b>(run: 이어지다, 뻗다)이에요. and로 이어지는 동사도 같은 주어의 동사라서 복수 현재 동사 <b>continue</b>(continue: 계속되다)가 맞아요. continuing은 동사가 될 수 없어요.","ex":"<b>down their tails</b>는 &ldquo;꼬리 쪽으로 내려가며&rdquo;라는 방향을 말하는 꾸밈말이에요.","st":[["s","짝 A","run (복수 동사)"],["c","접속사","and"],["s","짝 B","continue (복수 동사)"]],"verb":{"ok":"continue","no":"continuing"},"note":{"t":"앞 동사와 같은 모양으로 맞추기","lines":["run and → continue","앞 동사 run이 복수 동사 → 뒤도 복수 동사 continue (-ing 아님)"]}},{"no":"5","chunks":[{"en":"A person usually","ko":"사람은 보통","k":"","lab":""},{"en":"makes a number of mistakes in life","ko":"삶에서 많은 실수를 하고","k":"S","lab":"S 짝 A makes (단수동사)","h":[["makes","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"learns lessons from them.","ko":"그것들로부터 교훈을 배운다.","k":"V","lab":"V learns (learn 아님)"}],"tr":"사람은 보통 삶에서 많은 실수를 하고 그것들로부터 교훈을 배운다.","why":"주어 <b>A person</b>은 한 명이라서 <b>makes</b>(make: 하다)처럼 -s가 붙은 단수동사를 써요. and 뒤 동사도 같은 주어의 동사라서 <b>learn → learns</b>(learn: 배우다)로 고쳐요.","ex":"<b>a number of mistakes</b>의 a number of는 &ldquo;많은&rdquo;이라는 뜻이에요. 이 안의 mistakes(복수)는 동사의 수와 상관없어요.","st":[["s","짝 A","makes (단수동사)"],["c","접속사","and"],["s","짝 B","learn → learns"]],"verb":{"ok":"learns","no":"learn"},"note":{"t":"앞 동사의 수에 맞추기","lines":["makes and → learns","앞 동사 makes가 단수동사 → 뒤도 단수동사 learns"]}},{"no":"6","chunks":[{"en":"Some children do not speak often","ko":"어떤 아이들은 자주 말하지 않는다","k":"S","lab":"S 짝 A speak (동사원형)","h":[["speak","s"]]},{"en":"but","ko":"하지만","k":"C","lab":"C 접속사"},{"en":"express themselves clearly when they do.","ko":"스스로를 분명하게 표현한다, 말할 때는.","k":"V","lab":"V express (이미 맞음)"}],"tr":"어떤 아이들은 자주 말을 하지는 않지만 할 때는 스스로를 분명하게 표현한다.","why":"<b>do not speak</b>에서 not 뒤에는 동사원형 <b>speak</b>(speak: 말하다)이 와요. but으로 이어진 <b>express</b>(express: 표현하다)도 같은 자리의 동사원형이라서 맞아요. 고칠 곳이 없어요.","ex":"<b>when they do</b>에서 do는 앞의 동사(speak)를 대신 받는 말이에요. 뜻은 &ldquo;말을 할 때는&rdquo;.","st":[["s","짝 A","speak (동사원형)"],["c","접속사","but"],["s","짝 B","express (동사원형, 맞음)"]],"verb":{"ok":"express","no":"expressing"},"note":{"t":"앞 동사와 같은 모양으로 맞추기","lines":["speak but → express (맞음)","앞 동사 speak와 같은 동사원형 express. 고칠 곳 없음(○)"]}},{"no":"7","chunks":[{"en":"Serene quickly turned on one foot","ko":"세린은 재빨리 한 발로 돌았다","k":"S","lab":"S 짝 A turned (과거)","h":[["turned","s"]]},{"en":"in front of her friends","ko":"친구들 앞에서","k":"","lab":""},{"en":"but","ko":"하지만","k":"C","lab":"C 접속사"},{"en":"fell to the floor.","ko":"바닥에 넘어졌다.","k":"V","lab":"V fell (to fall 아님)"}],"tr":"Serene은 친구들 앞에서 재빨리 한 발로 돌았지만 바닥에 넘어졌다.","why":"앞의 동사 <b>turned</b>(turn: 돌다)가 과거 동사예요. but 뒤에도 과거 동사가 와야 해서 to부정사 <b>to fall</b>을 과거 동사 <b>fell</b>(fall: 넘어지다)로 고쳐요. fall은 과거형이 fell인 불규칙 동사예요.","ex":"<b>turn on one foot</b>은 &ldquo;한 발로 서서 돌다&rdquo;라는 뜻이에요.","st":[["s","짝 A","turned (과거)"],["c","접속사","but"],["s","짝 B","to fall → fell (과거)"]],"verb":{"ok":"fell","no":"to fall"},"note":{"t":"앞 동사의 시제에 맞추기","lines":["turned but → fell","앞 동사 turned가 과거 → 뒤도 과거 fell (to fall 아님)"]}},{"no":"8","chunks":[{"en":"Cut unnecessary expenses","ko":"불필요한 비용을 줄이고","k":"S","lab":"S 짝 A Cut (명령문 동사원형)","h":[["Cut","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"start saving","ko":"저축하기를 시작해라","k":"V","lab":"V start (이미 맞음)"},{"en":"if you want","ko":"당신이 원한다면","k":"","lab":""},{"en":"to achieve your financial goals more quickly.","ko":"재정적인 목표를 더 빨리 달성하기를.","k":"","lab":""}],"tr":"당신의 재정적인 목표를 더 빨리 달성하기를 원한다면 불필요한 비용을 줄이고 저축을 시작해라.","why":"동사원형으로 시작하는 문장은 &ldquo;~해라&rdquo;(명령문)예요. <b>Cut</b>(cut: 줄이다)과 and로 이어진 <b>start</b>(start: 시작하다)도 동사원형이라서 맞아요. 고칠 곳이 없어요.","ex":"<b>start saving</b>은 &ldquo;저축하기 시작하다&rdquo;(start + -ing)예요. 이 saving은 start의 목적어라서 병렬과는 상관없어요.","st":[["s","짝 A","Cut (명령문 동사원형)"],["c","접속사","and"],["s","짝 B","start (동사원형, 맞음)"]],"verb":{"ok":"start","no":"starting"},"note":{"t":"앞 동사와 같은 모양으로 맞추기","lines":["Cut and → start (맞음)","명령문 Cut(동사원형) → 뒤도 동사원형 start. 고칠 곳 없음(○)"]}}],"taps":[{"k":"C","t":"and / but / or를 누르세요"},{"k":"S","t":"앞에 이어진 동사(짝)를 누르세요"}],"cprompt":"맞는 동사를 고르세요"},{"id":"c08p2","page":95,"title":"POINT 2","sub":"동명사와 to부정사 병렬","prompt":"and / but / or를 누르세요","pnote":{"t":"-ing는 -ing끼리, to는 to끼리","lines":["동명사(-ing) + 동명사 / to부정사 + to부정사","뒤에 이어지는 to부정사의 to는 생략할 수 있다"]},"items":[{"no":"예제","chunks":[{"en":"An advertisement cannot meet its goal","ko":"광고는 그 목표를 달성할 수 없다","k":"","lab":""},{"en":"to create an appealing image","ko":"매력적인 이미지를 만들어 내는","k":"","lab":""},{"en":"by telling too many stories","ko":"너무 많은 이야기를 함으로써","k":"S","lab":"S 짝 A telling (동명사)","h":[["telling","s"]]},{"en":"or","ko":"또는","k":"C","lab":"C 접속사"},{"en":"showing everything.","ko":"모든 것을 보여줌으로써.","k":"V","lab":"V showing (to show 아님)"}],"tr":"광고는 너무 많은 이야기를 하는 것이나 모든 것을 보여주는 것에 의해 매력적인 이미지를 만들어 내는 목표를 달성할 수 없다.","why":"<b>by</b>는 전치사라서 뒤에 동명사가 와요. 그래서 A는 동명사 <b>telling</b>(tell: 말하다)이에요. or 뒤의 B도 같은 동명사 <b>showing</b>(show: 보여주다)으로 맞춰요. to show는 to부정사라서 안 돼요.","ex":"<b>to create an appealing image</b>는 goal(목표)을 꾸며 주는 to부정사예요. &ldquo;매력적인 이미지를 만들어 내는&rdquo;이라는 뜻이고, telling / showing과는 다른 덩어리예요.","st":[["s","짝 A","telling (by의 목적어, 동명사)"],["c","접속사","or"],["s","짝 B","showing (동명사)"]],"verb":{"ok":"showing","no":"to show"},"note":{"t":"-ing는 -ing끼리","lines":["by telling or → showing","by 뒤 telling이 동명사 → 짝도 동명사 showing"]}},{"no":"1","chunks":[{"en":"Kevin gave the old man enough money","ko":"케빈은 그 노인에게 충분한 돈을 주었다","k":"","lab":""},{"en":"not only","ko":"~뿐 아니라","k":"C","lab":"C 접속사 not only ~ but"},{"en":"to take a bus,","ko":"버스를 탈","k":"S","lab":"S 짝 A to take (to부정사)","h":[["to take","s"]]},{"en":"but","ko":"또한","k":"C","lab":"C 접속사 not only ~ but"},{"en":"to get a warm meal.","ko":"따뜻한 식사를 할.","k":"V","lab":"V to get (getting 아님)"}],"tr":"Kevin은 그 노인에게 버스를 탈 뿐만 아니라 따뜻한 식사를 할 충분한 돈을 주었다.","why":"<b>not only A but (also) B</b>에서 A가 to부정사 <b>to take</b>(take: (차를) 타다)예요. 그래서 B도 to부정사 <b>to get</b>(get: 얻다, 먹다)으로 맞춰요. 둘 다 &ldquo;enough money(충분한 돈)&rdquo;를 꾸며 줘요.","ex":"<b>gave the old man enough money</b>는 &ldquo;그 노인에게 충분한 돈을 주었다&rdquo;예요. give A B(A에게 B를 주다) 모양이에요.","st":[["s","짝 A","to take (to부정사)"],["c","접속사","not only ~ but"],["s","짝 B","to get (to부정사)"]],"verb":{"ok":"to get","no":"getting"},"note":{"t":"to는 to끼리","lines":["to take but → to get","앞이 to부정사 to take → 짝도 to부정사 to get"]}},{"no":"2","chunks":[{"en":"To reduce paper waste,","ko":"종이 낭비를 줄이기 위해,","k":"","lab":""},{"en":"digital reports are preferred","ko":"디지털 보고서가 선호된다","k":"","lab":""},{"en":"instead of printing them","ko":"그것들을 인쇄하는 것 대신에","k":"S","lab":"S 짝 A printing (동명사)","h":[["printing","s"]]},{"en":"or","ko":"또는","k":"C","lab":"C 접속사"},{"en":"making copies of them.","ko":"그것들의 복사본을 만드는 것.","k":"V","lab":"V making (to make 아님)"}],"tr":"종이 낭비를 줄이기 위해, 인쇄하는 것이나 복사본을 만드는 것 대신에 디지털 보고서가 선호된다.","why":"<b>instead of</b>의 of는 전치사라서 뒤에 동명사가 와요. 그래서 A가 동명사 <b>printing</b>(print: 인쇄하다)이고, or 뒤 B도 동명사 <b>making</b>(make: 만들다)이 맞아요.","ex":"<b>To reduce paper waste</b>는 &ldquo;종이 낭비를 줄이기 위해&rdquo;(목적)라는 문장 앞 꾸밈말이에요. reduce: 줄이다.","st":[["s","짝 A","printing (동명사)"],["c","접속사","or"],["s","짝 B","making (동명사)"]],"verb":{"ok":"making","no":"to make"},"note":{"t":"-ing는 -ing끼리","lines":["instead of printing or → making","of 뒤 printing이 동명사 → 짝도 동명사 making"]}},{"no":"3","chunks":[{"en":"Taking notes is a good way","ko":"노트 필기를 하는 것은 좋은 방법이다","k":"","lab":""},{"en":"to understand,","ko":"이해하기 위한,","k":"S","lab":"S 짝 A to understand (to부정사)","h":[["to understand","s"]]},{"en":"remember,","ko":"기억하기 위한,","k":"S","lab":"S 짝 B remember (to 생략)","h":[["remember","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"review important information better.","ko":"중요한 정보를 더 잘 복습하기 위한.","k":"V","lab":"V review (reviewing 아님)"}],"tr":"노트 필기를 하는 것은 중요한 정보를 더 잘 이해하고, 기억하고, 복습하기 위한 좋은 방법이다.","why":"way(방법)를 꾸미는 to부정사 <b>to understand</b>(understand: 이해하다)와 <b>(to) remember</b>(remember: 기억하다)가 이어지고 있어요. 뒤쪽 to는 생략할 수 있어서 세 번째도 동사원형 <b>review</b>(review: 복습하다)가 맞아요.","ex":"<b>Taking notes</b>(노트 필기를 하는 것)는 동명사 주어라서 단수동사 is가 와요(CH01에서 배웠어요).","st":[["s","짝 A","to understand"],["s","짝 B","(to) remember (to 생략)"],["c","접속사","and"],["s","짝 C","(to) review (to 생략)"]],"verb":{"ok":"review","no":"reviewing"},"note":{"t":"to부정사끼리 (to는 생략 가능)","lines":["to understand, remember and → review","앞이 to부정사 → 짝도 (to) review. 뒤 to는 생략됨"]}},{"no":"4","chunks":[{"en":"Judy wakes up early in the morning","ko":"주디는 아침에 일찍 일어난다","k":"","lab":""},{"en":"both","ko":"둘 다","k":"C","lab":"C 접속사 both ~ and"},{"en":"to drink a cup of tea","ko":"차를 한 잔 마시기 위해","k":"S","lab":"S 짝 A to drink (to부정사)","h":[["to drink","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사 both ~ and"},{"en":"to do yoga.","ko":"요가를 하기 위해.","k":"V","lab":"V to do (doing 아님)"}],"tr":"Judy는 차를 한 잔 마시는 것과 요가를 하는 것 둘 다 하기 위해 아침에 일찍 일어난다.","why":"<b>both A and B</b>(A와 B 둘 다)에서 A가 to부정사 <b>to drink</b>(drink: 마시다)예요. 그래서 B도 to부정사 <b>to do</b>(do: 하다)로 맞춰요.","ex":"<b>wakes up</b>(wake up: 일어나다)은 주어 Judy에 맞춘 단수동사예요. 목적을 나타내는 to부정사 두 개가 &ldquo;~하기 위해&rdquo;로 이어졌어요.","st":[["s","짝 A","to drink (to부정사)"],["c","접속사","both ~ and"],["s","짝 B","to do (to부정사)"]],"verb":{"ok":"to do","no":"doing"},"note":{"t":"to는 to끼리","lines":["to drink and → to do","앞이 to부정사 to drink → 짝도 to부정사 to do"]}},{"no":"5","chunks":[{"en":"I love cooking dishes with new flavors,","ko":"나는 새로운 맛의 요리를 하는 것을 좋아하고,","k":"S","lab":"S 짝 A cooking (동명사)","h":[["cooking","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"sharing meals with my family","ko":"가족들과 식사를 함께 하는 것을","k":"V","lab":"V sharing (to share 아님)"},{"en":"to create happy memories.","ko":"행복한 기억을 만들기 위해.","k":"","lab":""}],"tr":"나는 새로운 맛의 요리를 하는 것과, 행복한 기억을 만들기 위해 가족들과 식사를 함께 하는 것을 좋아한다.","why":"<b>love</b>(love: 좋아하다)의 목적어로 동명사 <b>cooking</b>(cook: 요리하다)이 왔어요. and로 이어지는 B도 같은 동명사 <b>sharing</b>(share: 함께 나누다)으로 맞춰요.","ex":"맨 끝의 <b>to create happy memories</b>는 &ldquo;행복한 기억을 만들기 위해&rdquo;라는 목적이에요. 병렬의 짝이 아니라서 신경 쓰지 않아도 돼요.","st":[["s","짝 A","cooking (동명사)"],["c","접속사","and"],["s","짝 B","sharing (동명사)"]],"verb":{"ok":"sharing","no":"to share"},"note":{"t":"-ing는 -ing끼리","lines":["love cooking and → sharing","love의 목적어로 cooking이 동명사 → 짝도 동명사 sharing"]}}],"taps":[{"k":"C","t":"and / but / or 같은 이어 주는 말을 모두 누르세요"},{"k":"S","t":"앞에 이어진 동명사·to부정사(짝)를 누르세요"}],"cprompt":"맞는 말을 고르세요"},{"id":"c08p3","page":95,"title":"POINT 3","sub":"분사 병렬","prompt":"and / but / or를 누르세요","pnote":{"t":"분사는 분사·형용사와 잇는다","lines":["분사(-ing / -ed) + 분사 또는 형용사","동사·to부정사와는 이을 수 없다"]},"items":[{"no":"예제","chunks":[{"en":"You can train your brain","ko":"당신은 당신의 뇌를 훈련시킬 수 있다","k":"","lab":""},{"en":"to become relaxed","ko":"편안해지도록","k":"V","lab":"V relaxed (to relax 아님)"},{"en":"or","ko":"또는","k":"C","lab":"C 접속사"},{"en":"confident","ko":"자신감 있게","k":"S","lab":"S 짝 B confident (형용사)","h":[["confident","s"]]},{"en":"by repeating experiences.","ko":"경험을 반복함으로써.","k":"","lab":""}],"tr":"당신은 경험을 반복함으로써 당신의 뇌가 편안하거나 자신감 있게 되도록 훈련시킬 수 있다.","why":"<b>become</b>(become: ~이 되다) 뒤에는 상태를 말하는 보어가 와요. or 뒤의 <b>confident</b>(자신감 있는)가 형용사라서 앞도 형용사 역할을 하는 분사 <b>relaxed</b>(relax: 편안하게 하다 → 편안해진)가 맞아요. to relax는 동사 모양이라 형용사와 이을 수 없어요.","ex":"<b>by repeating experiences</b>는 &ldquo;경험을 반복함으로써&rdquo;(방법)예요. by 뒤에는 동명사 repeating(repeat: 반복하다)이 왔어요.","st":[["s","짝 A","relaxed (분사)"],["c","접속사","or"],["s","짝 B","confident (형용사)"]],"verb":{"ok":"relaxed","no":"to relax"},"note":{"t":"분사는 분사·형용사와","lines":["relaxed or → confident","confident가 형용사 → 짝도 분사(형용사처럼 씀) relaxed"]}},{"no":"1","chunks":[{"en":"You look a little tired","ko":"너는 약간 피곤해 보인다","k":"S","lab":"S 짝 A tired (분사)","h":[["tired","s"]]},{"en":"but","ko":"하지만","k":"C","lab":"C 접속사"},{"en":"excited","ko":"신나 보인다","k":"V","lab":"V excited (이미 맞음)"},{"en":"after starting the project.","ko":"그 프로젝트를 시작한 이후로.","k":"","lab":""}],"tr":"그 프로젝트를 시작한 이후로 너는 약간 피곤하지만 신나 보인다.","why":"<b>look</b>(look: ~해 보이다) 뒤에 보어가 와요. <b>tired</b>(피곤한)와 but으로 이어진 <b>excited</b>(excite: 신나게 하다 → 신난)도 같은 분사라서 맞아요. 사람이 신나는 감정을 &ldquo;느끼니까&rdquo; -ed예요. 고칠 곳이 없어요.","ex":"<b>after starting the project</b>는 &ldquo;프로젝트를 시작한 후에&rdquo;예요. after 뒤에 동명사 starting이 왔어요.","st":[["s","짝 A","tired (분사)"],["c","접속사","but"],["s","짝 B","excited (분사, 맞음)"]],"verb":{"ok":"excited","no":"excite"},"note":{"t":"분사끼리 잇기","lines":["tired but → excited (맞음)","tired(분사)와 같은 분사 excited. 고칠 곳 없음(○)"]}},{"no":"2","chunks":[{"en":"Close friends can provide comfort","ko":"친한 친구들은 위안을 제공할 수 있다","k":"","lab":""},{"en":"to discouraged","ko":"낙담한","k":"V","lab":"V discouraged (discourage 아님)"},{"en":"or","ko":"또는","k":"C","lab":"C 접속사"},{"en":"unhappy teenagers.","ko":"불행한 십 대들에게.","k":"S","lab":"S 짝 B unhappy (형용사)","h":[["unhappy","s"]]}],"tr":"가까운 친구들은 낙담하거나 불행한 십 대들에게 위안을 제공할 수 있다.","why":"or 뒤의 <b>unhappy</b>(불행한)는 teenagers(십 대들)를 꾸미는 형용사예요. 앞의 discourage도 teenagers를 꾸며야 하므로 분사가 와야 해요. 십 대들이 낙담을 &ldquo;느끼는&rdquo; 쪽이라서 과거분사 <b>discouraged</b>(discourage: 낙담시키다 → 낙담한)로 고쳐요.","ex":"<b>provide comfort to ~</b>는 &ldquo;~에게 위안을 주다&rdquo;예요. provide: 제공하다.","st":[["s","짝 A","discourage → discouraged"],["c","접속사","or"],["s","짝 B","unhappy (형용사)"]],"verb":{"ok":"discouraged","no":"discourage"},"note":{"t":"분사는 분사·형용사와","lines":["discouraged or → unhappy","unhappy가 형용사 → 짝도 분사 discouraged (동사 아님)"]}},{"no":"3","chunks":[{"en":"The team’s research topic is very new","ko":"그 팀의 연구 주제는 매우 새롭다","k":"S","lab":"S 짝 A new (형용사)","h":[["new","s"]]},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"interesting,","ko":"흥미롭다,","k":"V","lab":"V interesting (interests 아님)"},{"en":"so it is receiving a lot of attention.","ko":"그래서 그것은 많은 관심을 받고 있다.","k":"","lab":""}],"tr":"그 팀의 연구 주제가 매우 새롭고 흥미로워서, 그것은 많은 관심을 받고 있다.","why":"<b>is</b> 뒤의 보어 <b>new</b>(새로운)는 형용사예요. and 뒤에도 형용사 역할을 하는 분사가 와야 해요. interests는 동사(interest: 흥미를 끌다)의 -s 모양이라 안 돼요. 연구 주제가 흥미를 &ldquo;주는&rdquo; 쪽이라서 현재분사 <b>interesting</b>(흥미로운)으로 고쳐요.","ex":"<b>so it is receiving a lot of attention</b>은 &ldquo;그래서 많은 관심을 받고 있다&rdquo;(결과)예요. receive: 받다.","st":[["s","짝 A","new (형용사)"],["c","접속사","and"],["s","짝 B","interests → interesting"]],"verb":{"ok":"interesting","no":"interests"},"note":{"t":"형용사는 형용사·분사와","lines":["new and → interesting","new가 형용사 → 짝도 형용사 모양 interesting (동사 interests 아님)"]}},{"no":"4","chunks":[{"en":"Noam will join a tennis club","ko":"노암은 테니스 클럽에 가입할 것이다","k":"","lab":""},{"en":"even though he is","ko":"비록 그가 ~이지만","k":"","lab":""},{"en":"neither","ko":"둘 다 아닌","k":"C","lab":"C 접속사 neither ~ nor"},{"en":"drawn to sports","ko":"스포츠에 끌리는","k":"S","lab":"S 짝 A drawn (과거분사)","h":[["drawn","s"]]},{"en":"nor","ko":"~도","k":"C","lab":"C 접속사 neither ~ nor"},{"en":"skilled at them.","ko":"그것들에 능숙한.","k":"V","lab":"V skilled (이미 맞음)"}],"tr":"Noam은 스포츠에 끌리거나 능숙한 것 둘 다 아니지만 테니스 클럽에 가입할 것이다.","why":"<b>neither A nor B</b>(A도 B도 아닌)에서 A가 <b>drawn</b>(draw: 끌어당기다 → 끌리는)이라는 과거분사예요. 그래서 B도 분사 <b>skilled</b>(능숙한)로 맞아요. 고칠 곳이 없어요.","ex":"<b>even though</b>는 &ldquo;비록 ~일지라도&rdquo;라는 뜻의 접속사예요(CH09에서 자세히 배워요). be drawn to ~ = ~에 끌리다.","st":[["s","짝 A","drawn (과거분사)"],["c","접속사","neither ~ nor"],["s","짝 B","skilled (분사, 맞음)"]],"verb":{"ok":"skilled","no":"skill"},"note":{"t":"분사끼리 잇기","lines":["drawn nor → skilled (맞음)","drawn(과거분사)과 같은 분사 skilled. 고칠 곳 없음(○)"]}},{"no":"5","chunks":[{"en":"Before I went up on stage to speak,","ko":"내가 연설하기 위해 무대에 오르기 전에,","k":"","lab":""},{"en":"Ms. Miller gave me","ko":"밀러 씨는 나에게 주었다","k":"","lab":""},{"en":"encouraging","ko":"힘을 북돋아 주는","k":"V","lab":"V encouraging (to encourage 아님)"},{"en":"and","ko":"그리고","k":"C","lab":"C 접속사"},{"en":"useful advice.","ko":"유용한 조언을.","k":"S","lab":"S 짝 B useful (형용사)","h":[["useful","s"]]}],"tr":"내가 연설하기 위해 무대에 오르기 전에, Miller씨는 나에게 힘을 북돋아 주고 유용한 조언을 해주었다.","why":"and 뒤의 <b>useful</b>(유용한)은 advice(조언)를 꾸미는 형용사예요. 그래서 앞도 advice를 꾸미는 분사가 와야 해요. 조언이 힘을 &ldquo;북돋아 주는&rdquo; 쪽이라서 현재분사 <b>encouraging</b>(encourage: 북돋우다 → 힘을 북돋아 주는)으로 고쳐요. to encourage는 안 돼요.","ex":"<b>went up on stage to speak</b>에서 to speak는 &ldquo;연설하기 위해&rdquo;(목적)예요. go up: 올라가다.","st":[["s","짝 A","to encourage → encouraging"],["c","접속사","and"],["s","짝 B","useful (형용사)"]],"verb":{"ok":"encouraging","no":"to encourage"},"note":{"t":"분사는 분사·형용사와","lines":["encouraging and → useful","useful이 형용사 → 짝도 분사 encouraging (to부정사 아님)"]}}],"taps":[{"k":"C","t":"and / but / or 같은 이어 주는 말을 모두 누르세요"},{"k":"S","t":"짝이 되는 분사·형용사를 누르세요"}],"cprompt":"맞는 말을 고르세요"},{"id":"c08q1","page":96,"title":"문장 연습 네모","sub":"둘 중 어법에 맞는 것 고르기","prompt":"연결어를 누르세요","pnote":{"t":"연결어 앞뒤는 같은 모양으로","lines":["and / or / but 앞뒤 → 같은 형태(동사원형끼리, v-ing끼리 등)","앞 짝의 모양을 먼저 찾아 뒤 짝도 똑같이 맞춘다"]},"items":[{"no":"1","chunks":[{"en":"You must lock the doors","ko":"당신은 문을 잠그고","k":"S","lab":"S 짝 A lock (동사원형)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"turn off the lights","ko":"불을 꺼야 한다","k":"V","lab":"V turn (to turn 아님)"},{"en":"before you leave the house.","ko":"집을 떠나기 전에.","k":"","lab":""}],"tr":"당신은 집을 떠나기 전에 문을 잠그고 불을 꺼야 한다.","why":"조동사 <b>must</b> 뒤에 동사원형 <b>lock</b>(lock: 잠그다)이 있어요. and로 이어지는 동사도 같은 must 뒤라서 동사원형 <b>turn</b>(turn off: 끄다)이 맞아요. to turn은 동사가 아니라서 짝이 될 수 없어요.","ex":"<b>before you leave the house</b>는 &ldquo;집을 떠나기 전에&rdquo;예요. leave: 떠나다.","st":[["s","짝 A","lock (동사원형)"],["c","접속사","and"],["s","짝 B","turn (동사원형)"]],"verb":{"ok":"turn","no":"to turn"},"note":{"t":"and 뒤는 앞 짝과 같은 모양","lines":["lock ↔ turn (둘 다 동사원형)","must 뒤 동사원형 짝 → turn(끄다). to turn은 아님"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"2","chunks":[{"en":"By exercising regularly","ko":"규칙적으로 운동하는 것과","k":"S","lab":"S 짝 A exercising (동명사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"maintaining a balanced diet,","ko":"균형 잡힌 식단을 유지하는 것에 의해,","k":"V","lab":"V maintaining (maintain 아님)"},{"en":"she hoped to improve her overall health.","ko":"그녀는 전반적인 건강을 개선하기를 희망했다.","k":"","lab":""}],"tr":"규칙적으로 운동하는 것과 균형 잡힌 식단을 유지하는 것에 의해, 그녀는 전반적인 건강을 개선하기를 희망했다.","why":"<b>By</b>는 전치사라서 뒤에 동명사가 와요. A가 동명사 <b>exercising</b>(exercise: 운동하다)이니까 B도 동명사 <b>maintaining</b>(maintain: 유지하다)이 맞아요.","ex":"<b>she hoped to improve ~</b>는 &ldquo;그녀는 ~을 개선하기를 바랐다&rdquo;예요. hope to V: V하기를 바라다.","st":[["s","짝 A","exercising (동명사)"],["c","접속사","and"],["s","짝 B","maintaining (동명사)"]],"verb":{"ok":"maintaining","no":"maintain"},"note":{"t":"전치사 뒤 짝은 동명사끼리","lines":["exercising ↔ maintaining","By(~에 의해) 뒤 동명사 짝 → maintaining(유지하는 것)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"3","chunks":[{"en":"On weekends, my husband and I","ko":"주말에, 나의 남편과 나는","k":"","lab":""},{"en":"either go hiking","ko":"등산을 하거나","k":"S","lab":"S 짝 A go (동사원형)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 either ~ or"},{"en":"play board games at home.","ko":"집에서 보드게임을 한다.","k":"V","lab":"V play (playing 아님)"}],"tr":"주말에, 나의 남편과 나는 등산을 하거나 집에서 보드게임을 하는 것 중 하나를 한다.","why":"<b>either A or B</b>(둘 중 하나)에서 A는 <b>go</b>(go: 가다)예요. 주어 my husband and I가 복수라서 동사원형이고, B도 같은 동사원형 <b>play</b>(play: 하다, 놀다)로 맞춰요. playing은 동사가 아니에요.","ex":"<b>go hiking</b>은 &ldquo;등산하러 가다&rdquo;예요(go + -ing). 이 hiking은 go 뒤에 붙은 말이라 병렬의 짝이 아니에요.","st":[["s","짝 A","go (동사원형)"],["c","접속사","either ~ or"],["s","짝 B","play (동사원형)"]],"verb":{"ok":"play","no":"playing"},"note":{"t":"either ~ or 앞뒤는 같은 모양","lines":["go ↔ play (둘 다 동사원형)","주어 we(나와 남편) 뒤 동사원형 짝 → play(하다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"4","chunks":[{"en":"Marco travels to many places","ko":"마르코는 많은 장소들을 여행하고","k":"S","lab":"S 짝 A travels (단수동사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"takes beautiful photographs as a travel blogger.","ko":"여행 블로거로서 아름다운 사진을 찍는다.","k":"V","lab":"V takes (take 아님)"}],"tr":"Marco는 여행 블로거로서 많은 장소들을 여행하고 아름다운 사진을 찍는다.","why":"주어 <b>Marco</b>는 한 명이라서 <b>travels</b>(travel: 여행하다)처럼 -s가 붙은 단수동사를 써요. and 뒤의 동사도 같은 주어의 단수동사 <b>takes</b>(take: (사진을) 찍다)가 맞아요.","ex":"<b>as a travel blogger</b>의 as는 &ldquo;~로서&rdquo;라는 뜻이에요(CH09에서 자세히 배워요). blogger: 블로그를 쓰는 사람.","st":[["s","짝 A","travels (단수동사)"],["c","접속사","and"],["s","짝 B","takes (단수동사)"]],"verb":{"ok":"takes","no":"take"},"note":{"t":"같은 주어의 동사 짝은 같은 시제·수","lines":["travels ↔ takes (단수동사)","주어 Marco 하나에 동사 두 개 → takes(찍다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"5","chunks":[{"en":"The key to success is not rushing","ko":"성공의 열쇠는 서두르는 것이","k":"S","lab":"S 짝 A rushing (동명사)"},{"en":"to finish every task quickly","ko":"모든 일을 빠르게 끝내려고","k":"","lab":""},{"en":"but","ko":"아니라","k":"C","lab":"C 연결어 not ~ but"},{"en":"carefully planning each one before starting.","ko":"시작하기 전에 각각의 것을 신중하게 계획하는 것이다.","k":"V","lab":"V planning (to plan 아님)"}],"tr":"성공의 열쇠는 모든 일을 빠르게 끝내기 위해 서두르는 것이 아니라 시작하기 전에 각각의 것을 신중하게 계획하는 것이다.","why":"<b>not A but B</b>(A가 아니라 B)에서 A는 <b>rushing</b>(rush: 서두르다)이라는 동명사예요. is의 보어 자리라서 B도 동명사 <b>planning</b>(plan: 계획하다)이 맞아요.","ex":"A 덩어리 <b>rushing to finish every task quickly</b> 안의 to finish(끝내기 위해)는 짝을 고를 때 신경 쓰지 않아도 돼요. 부사 carefully(신중하게)는 B를 꾸미는 말이에요.","st":[["s","짝 A","rushing (동명사)"],["c","접속사","not ~ but"],["s","짝 B","planning (동명사)"]],"verb":{"ok":"planning","no":"to plan"},"note":{"t":"not ~ but 앞뒤는 같은 모양","lines":["rushing ↔ planning (둘 다 동명사)","is 뒤 보어 짝 → planning(계획하는 것)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"6","chunks":[{"en":"We have gathered in this meeting room","ko":"우리는 이 회의실에 모였다","k":"","lab":""},{"en":"to share ideas","ko":"아이디어를 공유하기 위해","k":"S","lab":"S 짝 A to share (to부정사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"find the best solution.","ko":"최선의 해결책을 찾기 위해.","k":"V","lab":"V find (finding 아님)"}],"tr":"우리는 아이디어를 공유하고 최선의 해결책을 찾기 위해 이 회의실에 모였다.","why":"목적을 나타내는 to부정사 <b>to share</b>(share: 공유하다)가 있고, and 뒤에는 같은 to부정사가 와야 해요. 뒤쪽 to는 생략할 수 있어서 동사원형 <b>find</b>(find: 찾다)가 맞아요.","ex":"<b>have gathered</b>는 gather(모이다)의 현재완료(have + p.p.)예요. &ldquo;모였다&rdquo;.","st":[["s","짝 A","to share (to부정사)"],["c","접속사","and"],["s","짝 B","(to) find (to 생략)"]],"verb":{"ok":"find","no":"finding"},"note":{"t":"and 뒤는 앞 to부정사의 짝","lines":["to share ↔ (to) find","두 번째 to는 생략 가능 → 동사원형 find(찾다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"7","chunks":[{"en":"Take time to check your progress","ko":"당신의 진행 상황을 점검할 시간을 갖고","k":"S","lab":"S 짝 A Take (명령문 동사원형)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"set new goals for the future.","ko":"미래를 위해 새로운 목표를 설정하라.","k":"V","lab":"V set (setting 아님)"}],"tr":"당신의 진행 상황을 점검할 시간을 갖고 미래를 위해 새로운 목표를 설정하라.","why":"and가 이어 주는 짝의 모양을 맞추는 문제예요. 명령문은 동사원형으로 시작해요. <b>Take</b>(take: 갖다)와 and로 이어진 동사도 동사원형 <b>set</b>(set: 설정하다)이 맞아요. <b>to check ~ and (to) set</b>으로 읽어도 답은 set이에요. 어느 쪽으로 읽어도 동사 모양이 필요해서 setting은 안 돼요.","ex":"짝은 Take와 set이에요. <b>time to check ~</b>는 &ldquo;~을 점검할 시간&rdquo;이에요.","st":[["s","짝 A","Take (명령문)"],["c","접속사","and"],["s","짝 B","set (동사원형)"]],"verb":{"ok":"set","no":"setting"},"note":{"t":"명령문 짝은 동사원형끼리","lines":["Take ↔ set (둘 다 동사원형)","명령문(~하라) 두 개를 and로 이음 → set(정하다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"8","chunks":[{"en":"Mandy often shops for vegetables at the local market","ko":"맨디는 종종 지역 시장에서 채소를 사거나","k":"S","lab":"S 짝 A shops (단수동사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"walks around her neighborhood when she is free.","ko":"한가할 때 동네를 걸어 다닌다.","k":"V","lab":"V walks (walk 아님)"}],"tr":"Mandy는 한가할 때 종종 지역 시장에서 채소를 사거나 동네를 걸어 다닌다.","why":"주어 <b>Mandy</b>는 한 명이라서 <b>shops</b>(shop: 쇼핑하다)처럼 단수동사를 써요. or 뒤의 동사도 같은 주어의 단수동사 <b>walks</b>(walk: 걸어 다니다)가 맞아요.","ex":"<b>when she is free</b>는 &ldquo;한가할 때&rdquo;예요. shop for ~ = ~을 사러 다니다.","st":[["s","짝 A","shops (단수동사)"],["c","접속사","or"],["s","짝 B","walks (단수동사)"]],"verb":{"ok":"walks","no":"walk"},"note":{"t":"같은 주어의 동사 짝은 같은 수","lines":["shops ↔ walks (단수동사)","주어 Mandy 하나 → walks(걷다). walk는 아님"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"9","chunks":[{"en":"I finished washing the dishes,","ko":"나는 접시를 닦는 것을 끝냈지만,","k":"S","lab":"S 짝 A finished (과거)"},{"en":"but","ko":"그러나","k":"C","lab":"C 연결어 but"},{"en":"put off cleaning the bathroom until tomorrow.","ko":"내일까지 화장실을 청소하는 것을 미뤘다.","k":"V","lab":"V put (putting 아님)"}],"tr":"나는 접시를 닦는 것은 끝냈지만, 화장실을 청소하는 것은 내일까지 미뤘다.","why":"앞의 동사 <b>finished</b>(finish: 끝내다)가 과거 동사예요. but 뒤에도 과거 동사 <b>put</b>(put off: 미루다)이 와야 해요. put은 원형·과거형이 똑같은 모양이에요. putting은 동사가 아니라서 안 돼요.","ex":"<b>finished washing</b>, <b>put off cleaning</b>처럼 finish와 put off 뒤에는 동명사(-ing)가 와요. 이 -ing는 병렬의 짝이 아니에요.","st":[["s","짝 A","finished (과거)"],["c","접속사","but"],["s","짝 B","put (과거)"]],"verb":{"ok":"put","no":"putting"},"note":{"t":"but 앞뒤 동사는 시제를 맞추기","lines":["finished ↔ put (둘 다 과거)","put(미루다)은 과거형도 put. 주어 I에 동사 두 개"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"10","chunks":[{"en":"The hotel would like to hire","ko":"그 호텔은 고용하고 싶어 한다","k":"","lab":""},{"en":"a professional","ko":"전문적인","k":"S","lab":"S 짝 A professional (형용사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"experienced manager","ko":"경험 있는 매니저를","k":"V","lab":"V experienced (experience 아님)"},{"en":"for better service.","ko":"더 나은 서비스를 위해.","k":"","lab":""}],"tr":"그 호텔은 더 나은 서비스를 위해 전문적이고 경험 있는 매니저를 고용하고 싶어 한다.","why":"<b>professional</b>(전문적인)은 manager(매니저)를 꾸미는 형용사예요. and 뒤에도 manager를 꾸미는 말이 와야 해서 분사 <b>experienced</b>(experience: 경험하다 → 경험 있는)가 맞아요. 명사 experience(경험)는 이을 수 없어요.","ex":"<b>would like to V</b>는 &ldquo;V하고 싶다&rdquo;예요. hire: 고용하다.","st":[["s","짝 A","professional (형용사)"],["c","접속사","and"],["s","짝 B","experienced (분사)"]],"verb":{"ok":"experienced","no":"experience"},"note":{"t":"manager를 꾸미는 말은 형용사끼리","lines":["professional ↔ experienced","매니저를 꾸미는 말 → 형용사 짝. experience는 명사"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"11","chunks":[{"en":"People respond differently to life’s challenges,","ko":"사람들은 삶의 도전들에 대해 다르게 반응한다,","k":"","lab":""},{"en":"like taking an exam to enter a school","ko":"~와 같은, 학교에 입학하기 위해 시험을 치르는 것","k":"S","lab":"S 짝 A taking (동명사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"getting surgery.","ko":"수술을 받는 것.","k":"V","lab":"V getting (to get 아님)"}],"tr":"사람들은 학교에 입학하기 위해 시험을 치르는 것이나 수술을 받는 것과 같은 삶의 도전들에 대해 다르게 반응한다.","why":"<b>like</b>는 여기서 &ldquo;~와 같은&rdquo;이라는 전치사라서 뒤에 동명사가 와요. A가 동명사 <b>taking</b>(take: (시험을) 치르다)이니까 B도 동명사 <b>getting</b>(get: 받다)이 맞아요.","ex":"A 덩어리 안의 <b>to enter a school</b>은 &ldquo;학교에 입학하기 위해&rdquo;(목적)예요. 이것 때문에 to get을 고르면 안 돼요.","st":[["s","짝 A","taking (like의 목적어, 동명사)"],["c","접속사","or"],["s","짝 B","getting (동명사)"]],"verb":{"ok":"getting","no":"to get"},"note":{"t":"전치사 like 뒤 짝은 동명사끼리","lines":["taking ↔ getting","like(~와 같은) 뒤 동명사 짝 → getting(받는 것)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"12","chunks":[{"en":"In Greece, if a stranger appeared at your door,","ko":"그리스에서는, 낯선 사람이 당신의 문 앞에 나타나면,","k":"","lab":""},{"en":"it was your duty","ko":"그것은 당신의 의무였다","k":"","lab":""},{"en":"to show kindness,","ko":"친절을 보이는 것,","k":"S","lab":"S 짝 A to show (to부정사)"},{"en":"to give him comforting shelter,","ko":"그에게 편안한 쉴 곳을 주는 것,","k":"S","lab":"S 짝 B to give (to부정사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"to serve him food.","ko":"그에게 음식을 대접하는 것.","k":"V","lab":"V to serve (serving 아님)"}],"tr":"그리스에서는, 낯선 사람이 당신의 문 앞에 나타나면, 친절을 보이는 것, 그에게 편안한 쉴 곳을 주는 것, 그리고 음식을 대접하는 것이 당신의 의무였다.","why":"<b>it</b>은 가짜 주어이고 진짜 주어는 <b>to show</b>(show: 보이다), <b>to give</b>(give: 주다)예요. 세 번째 짝도 같은 to부정사 <b>to serve</b>(serve: 대접하다)로 맞춰요. serving은 동명사라서 안 돼요.","ex":"<b>comforting shelter</b>는 &ldquo;편안함을 주는 쉴 곳&rdquo;이에요. 여기 comforting(comfort: 편안하게 하다)은 shelter를 꾸미는 분사예요. <b>it was your duty to ~</b> = ~하는 것이 당신의 의무였다.","st":[["s","짝 A","to show"],["s","짝 B","to give"],["c","접속사","and"],["s","짝 C","to serve (to부정사)"]],"verb":{"ok":"to serve","no":"serving"},"note":{"t":"나열은 모두 같은 모양으로","lines":["to show, to give, (and) to serve","세 짝이 모두 to부정사 → to serve(대접하다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]}],"cprompt":"맞는 말을 고르세요"},{"id":"c08q2","page":97,"title":"문장 연습 밑줄","sub":"밑줄 친 부분이 맞으면 O, 틀리면 고치기","prompt":"연결어를 누르세요","pnote":{"t":"밑줄 친 말을 앞 짝과 비교하기","lines":["and / or / but 앞 짝의 모양(형태·시제·수)을 찾는다","뒤 짝이 앞 짝과 다르면 고치고, 같으면 그대로 둔다"]},"items":[{"no":"1","chunks":[{"en":"Children are more capable of","ko":"어린이들은 더 능력이 있다","k":"","lab":""},{"en":"learning multiple languages","ko":"다수의 언어를 배우는 것","k":"S","lab":"S 짝 A learning (동명사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"adapting to new environments","ko":"새로운 환경에 적응하는 것","k":"V","lab":"V adapting (to adapt 아님)"},{"en":"than adults.","ko":"성인들보다.","k":"","lab":""}],"tr":"어린이들은 성인들보다 다수의 언어를 배우거나 새로운 환경에 적응할 더 많은 능력이 있다.","why":"<b>of</b>는 전치사라서 뒤에 동명사가 와요. A가 동명사 <b>learning</b>(learn: 배우다)이니까 or 뒤 B도 동명사로 맞춰야 해요. <b>to adapt → adapting</b>(adapt: 적응하다)으로 고쳐요.","ex":"<b>be capable of -ing</b>는 &ldquo;~할 능력이 있다&rdquo;예요. than adults(성인들보다)는 비교하는 말이에요.","st":[["s","짝 A","learning (동명사)"],["c","접속사","or"],["s","짝 B","to adapt → adapting"]],"verb":{"ok":"adapting","no":"to adapt"},"note":{"t":"전치사 of 뒤 짝은 동명사끼리","lines":["learning ↔ adapting","of(~의) 뒤 동명사 짝 → to adapt를 adapting(적응하는 것)으로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"2","chunks":[{"en":"When you first meet a German host,","ko":"당신이 독일인 행사 주최자를 처음 만날 때,","k":"","lab":""},{"en":"he will shake hands,","ko":"그는 악수하고,","k":"S","lab":"S 짝 A shake (동사원형)"},{"en":"greet everyone standing there,","ko":"거기에 서 있는 모든 사람들과 인사하고,","k":"S","lab":"S 짝 B greet (동사원형)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"even bow his head slightly.","ko":"심지어 고개를 약간 숙일 것이다.","k":"V","lab":"V bow (bowing 아님)"}],"tr":"당신이 독일인 행사 주최자를 처음 만날 때, 그는 악수하고, 거기에 서 있는 모든 사람들과 인사하고, 심지어 고개를 약간 숙일 것이다.","why":"조동사 <b>will</b> 뒤에 동사원형 <b>shake</b>(shake: 흔들다), <b>greet</b>(greet: 인사하다)가 나열돼 있어요. 마지막도 같은 동사원형이어야 해서 <b>bowing → bow</b>(bow: (고개를) 숙이다)로 고쳐요.","ex":"<b>shake hands</b>는 &ldquo;악수하다&rdquo;예요. <b>everyone standing there</b>는 &ldquo;거기에 서 있는 모든 사람&rdquo;(standing이 everyone을 꾸미는 분사).","st":[["s","짝 A","shake (동사원형)"],["s","짝 B","greet (동사원형)"],["c","접속사","and"],["s","짝 C","bowing → bow"]],"verb":{"ok":"bow","no":"bowing"},"note":{"t":"will 뒤 동사원형 짝","lines":["shake, greet, (and) bow","will(~할 것이다) 뒤 동사원형 셋 → bowing을 bow(숙이다)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"3","chunks":[{"en":"The artist spent hours","ko":"그 예술가는 몇 시간을 썼다","k":"","lab":""},{"en":"painting colors on the canvas","ko":"캔버스에 색깔을 칠하는 데","k":"S","lab":"S 짝 A painting (동명사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"expressing strong emotions.","ko":"강한 감정을 표현하는 데.","k":"V","lab":"V expressing (이미 맞음)"}],"tr":"그 예술가는 캔버스에 색깔을 칠하고 강한 감정을 표현하는 데 몇 시간을 썼다.","why":"<b>spend 시간 + -ing</b>(~하는 데 시간을 쓰다) 모양이에요. <b>painting</b>(paint: 칠하다)과 and로 이어진 <b>expressing</b>(express: 표현하다)도 같은 동명사라서 맞아요. 고칠 곳이 없어요.","ex":"spent는 spend(쓰다)의 과거형이에요.","st":[["s","짝 A","painting (동명사)"],["c","접속사","and"],["s","짝 B","expressing (동명사, 맞음)"]],"verb":{"ok":"expressing","no":"to express"},"note":{"t":"spend 시간 + v-ing, 짝도 v-ing","lines":["painting ↔ expressing (맞음)","spend(쓰다) 뒤는 v-ing → 고칠 곳 없음(O)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"4","chunks":[{"en":"After a long day at work, Sally","ko":"직장에서의 긴 하루 후에, 샐리는","k":"","lab":""},{"en":"goes for a run to clear her mind","ko":"마음을 비우기 위해 달리기를 하러 가거나","k":"S","lab":"S 짝 A goes (단수동사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"takes a warm bath.","ko":"따뜻한 목욕을 한다.","k":"V","lab":"V takes (take 아님)"}],"tr":"직장에서의 긴 하루 후에, Sally는 마음을 비우기 위해 달리기를 하러 가거나 따뜻한 목욕을 한다.","why":"주어 <b>Sally</b>는 한 명이라서 <b>goes</b>(go: 가다)처럼 단수동사를 써요. or로 이어진 동사도 같은 주어의 단수동사여야 해서 <b>take → takes</b>(take: (목욕을) 하다)로 고쳐요.","ex":"<b>to clear her mind</b>는 &ldquo;마음을 비우기 위해&rdquo;(목적)예요. 하지만 뜻을 보면 &ldquo;목욕을 한다&rdquo;는 Sally가 하는 행동이라서 to clear가 아니라 goes와 짝이에요.","st":[["s","짝 A","goes (단수동사)"],["c","접속사","or"],["s","짝 B","take → takes (단수동사)"]],"verb":{"ok":"takes","no":"take"},"note":{"t":"같은 주어의 동사 짝은 같은 수","lines":["goes ↔ takes (단수동사)","주어 Sally 하나 → take를 takes(하다)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"5","chunks":[{"en":"The book is filled with","ko":"그 책은 가득 차 있다","k":"","lab":""},{"en":"both","ko":"둘 다","k":"C","lab":"C 연결어 both ~ and"},{"en":"inspiring","ko":"영감을 주는","k":"S","lab":"S 짝 A inspiring (분사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"pleasing stories","ko":"즐거운 이야기들로","k":"V","lab":"V pleasing (pleases 아님)"},{"en":"for all kinds of readers.","ko":"모든 종류의 독자들에게.","k":"","lab":""}],"tr":"그 책은 모든 종류의 독자들에게 영감을 주고 즐거운 이야기로 가득 차 있다.","why":"<b>both A and B</b>에서 A는 stories(이야기들)를 꾸미는 분사 <b>inspiring</b>(inspire: 영감을 주다 → 영감을 주는)이에요. B도 stories를 꾸미는 분사여야 해서 <b>pleases → pleasing</b>(please: 즐겁게 하다 → 즐거운)으로 고쳐요. 이야기가 즐거움을 &ldquo;주는&rdquo; 쪽이라 -ing예요.","ex":"<b>be filled with ~</b>는 &ldquo;~로 가득 차 있다&rdquo;예요.","st":[["s","짝 A","inspiring (분사)"],["c","접속사","both ~ and"],["s","짝 B","pleases → pleasing"]],"verb":{"ok":"pleasing","no":"pleases"},"note":{"t":"stories를 꾸미는 말은 같은 모양","lines":["inspiring ↔ pleasing (둘 다 분사)","이야기를 꾸미는 말 → pleases를 pleasing(즐거운)으로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"6","chunks":[{"en":"As soon as the teacher entered the room,","ko":"선생님이 방에 들어오자마자,","k":"","lab":""},{"en":"the students stopped talking","ko":"학생들은 이야기하는 것을 멈추고","k":"S","lab":"S 짝 A stopped (과거)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"sat quietly in their seats.","ko":"조용히 그들의 자리에 앉았다.","k":"V","lab":"V sat (sitting 아님)"}],"tr":"선생님이 방에 들어오자마자, 학생들은 이야기하는 것을 멈추고 조용히 그들의 자리에 앉았다.","why":"주어 the students의 동사 <b>stopped</b>(stop: 멈추다)가 과거 동사예요. and로 이어진 동사도 과거 동사여야 해서 <b>sitting → sat</b>(sit: 앉다)로 고쳐요. sit의 과거형은 sat이에요.","ex":"<b>stopped talking</b>(이야기하는 것을 멈췄다)의 talking은 stop의 목적어라서, sitting의 짝이 아니에요. <b>As soon as ~</b>는 &ldquo;~하자마자&rdquo;예요.","st":[["s","짝 A","stopped (과거)"],["c","접속사","and"],["s","짝 B","sitting → sat (과거)"]],"verb":{"ok":"sat","no":"sitting"},"note":{"t":"같은 주어의 동사 짝은 같은 시제","lines":["stopped ↔ sat (둘 다 과거)","과거 이야기 → sitting을 sat(앉았다)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"7","chunks":[{"en":"Put your plans down on paper","ko":"당신의 계획을 종이에 적어라","k":"","lab":""},{"en":"not only","ko":"~뿐만 아니라","k":"C","lab":"C 연결어 not only"},{"en":"to help with brainstorming","ko":"브레인스토밍을 돕기 위해서","k":"S","lab":"S 짝 A to help (to부정사)"},{"en":"but also","ko":"또한","k":"C","lab":"C 연결어 but also"},{"en":"to make your thoughts clear.","ko":"당신의 생각을 분명하게 만들기 위해.","k":"V","lab":"V to make (이미 맞음)"}],"tr":"브레인스토밍을 돕기 위해서뿐만 아니라 당신의 생각을 분명하게 만들기 위해 당신의 계획을 종이에 적어라.","why":"<b>not only A but also B</b>에서 A가 to부정사 <b>to help</b>(help: 돕다)예요. B도 to부정사 <b>to make</b>(make: 만들다)라서 맞아요. 고칠 곳이 없어요.","ex":"<b>make your thoughts clear</b>는 &ldquo;당신의 생각을 분명하게 만들다&rdquo;예요(make + 목적어 + 형용사).","st":[["s","짝 A","to help (to부정사)"],["c","접속사","not only ~ but also"],["s","짝 B","to make (to부정사, 맞음)"]],"verb":{"ok":"to make","no":"making"},"note":{"t":"not only ~ but also 앞뒤는 같은 모양","lines":["to help ↔ to make (둘 다 to부정사)","짝이 같은 모양이라 고칠 곳 없음(O)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"8","chunks":[{"en":"To become a good writer,","ko":"좋은 작가가 되기 위해서,","k":"","lab":""},{"en":"practice writing daily","ko":"매일 글쓰기를 연습하고","k":"S","lab":"S 짝 A practice (명령문 동사원형)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"seek feedback from other people.","ko":"다른 사람들에게 의견을 구하라.","k":"V","lab":"V seek (to seek 아님)"}],"tr":"좋은 작가가 되기 위해서, 매일 글쓰기를 연습하고 다른 사람들에게 의견을 구하라.","why":"동사원형으로 시작하는 명령문(&ldquo;~해라&rdquo;)이에요. <b>practice</b>(practice: 연습하다)와 and로 이어진 동사도 동사원형이어야 해서 <b>to seek → seek</b>(seek: 구하다)로 고쳐요.","ex":"<b>To become a good writer</b>는 &ldquo;좋은 작가가 되기 위해서&rdquo;(목적)라는 문장 앞 꾸밈말이에요. writing daily는 practice의 목적어(매일 글쓰기를)예요.","st":[["s","짝 A","practice (명령문 동사원형)"],["c","접속사","and"],["s","짝 B","to seek → seek"]],"verb":{"ok":"seek","no":"to seek"},"note":{"t":"명령문 짝은 동사원형끼리","lines":["practice ↔ seek (둘 다 동사원형)","명령문(~하라) → to seek를 seek(구하다)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"9","chunks":[{"en":"Listening to others allows you","ko":"다른 사람의 말을 듣는 것은 당신에게 허락한다","k":"","lab":""},{"en":"to solve problems,","ko":"문제를 해결하고,","k":"S","lab":"S 짝 A to solve (to부정사)"},{"en":"gain new views,","ko":"새로운 관점을 얻고,","k":"S","lab":"S 짝 B gain (to 생략)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"learn from different experiences.","ko":"다양한 경험을 통해 배우는 것을.","k":"V","lab":"V learn (이미 맞음)"}],"tr":"다른 사람의 말을 듣는 것은 당신이 문제를 해결하고, 새로운 관점을 얻고, 다양한 경험을 통해 배울 수 있도록 허락한다.","why":"<b>allow A to V</b>(A가 V하도록 허락하다)에서 to부정사가 <b>to solve</b>(solve: 해결하다)로 시작해요. 뒤에 이어지는 <b>gain</b>(gain: 얻다), <b>learn</b>(learn: 배우다)은 to가 생략된 동사원형이라 맞아요. 고칠 곳이 없어요.","ex":"<b>Listening to others</b>(다른 사람의 말을 듣는 것)는 동명사 주어라서 단수동사 allows가 왔어요(CH01).","st":[["s","짝 A","to solve"],["s","짝 B","(to) gain (to 생략)"],["c","접속사","and"],["s","짝 C","(to) learn (to 생략, 맞음)"]],"verb":{"ok":"learn","no":"learning"},"note":{"t":"나열에서 to는 생략할 수 있다","lines":["to solve, (to) gain, (to) learn","짝이 모두 to부정사 모양 → 고칠 곳 없음(O)"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"10","chunks":[{"en":"My cat tries to catch birds in the garden","ko":"나의 고양이는 정원에서 새를 잡으려고 노력하지만","k":"S","lab":"S 짝 A tries (단수동사)"},{"en":"but","ko":"그러나","k":"C","lab":"C 연결어 but"},{"en":"fails every time.","ko":"매번 실패한다.","k":"V","lab":"V fails (to fail 아님)"}],"tr":"나의 고양이는 정원에서 새를 잡으려고 노력하지만 매번 실패한다.","why":"주어 <b>My cat</b>은 한 마리라서 <b>tries</b>(try: 노력하다)처럼 단수동사를 써요. but 뒤도 같은 주어의 동사여야 해서 <b>to fail → fails</b>(fail: 실패하다)로 고쳐요.","ex":"<b>to catch birds</b>는 tries의 목적어(새를 잡는 것)예요. 이 to catch를 보고 to fail이 짝이라고 착각하기 쉬운데, 짝은 동사 tries예요.","st":[["s","짝 A","tries (단수동사)"],["c","접속사","but"],["s","짝 B","to fail → fails (단수동사)"]],"verb":{"ok":"fails","no":"to fail"},"note":{"t":"같은 주어의 동사 짝은 같은 수","lines":["tries ↔ fails (단수동사)","주어 My cat 하나 → to fail을 fails(실패하다)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"11","chunks":[{"en":"The CEO agrees with","ko":"최고경영자는 ~에 동의한다","k":"","lab":""},{"en":"delaying the store opening","ko":"상점 개장을 미루는 것","k":"S","lab":"S 짝 A delaying (동명사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"taking more time to prepare for the event.","ko":"행사를 준비하기 위해 시간을 더 갖는 것에.","k":"V","lab":"V taking (to take 아님)"}],"tr":"CEO는 상점 개장을 미루는 것과 행사를 준비하기 위해 시간을 더 갖는 것에 동의한다.","why":"<b>with</b>는 전치사라서 뒤에 동명사가 와요. A가 동명사 <b>delaying</b>(delay: 미루다)이니까 B도 동명사로 맞춰야 해서 <b>to take → taking</b>(take: (시간을) 들이다)으로 고쳐요.","ex":"<b>to prepare for the event</b>는 &ldquo;행사를 준비하기 위해&rdquo;(목적)예요. agree with ~ = ~에 동의하다.","st":[["s","짝 A","delaying (동명사)"],["c","접속사","and"],["s","짝 B","to take → taking"]],"verb":{"ok":"taking","no":"to take"},"note":{"t":"전치사 with 뒤 짝은 동명사끼리","lines":["delaying ↔ taking","with(~에) 뒤 동명사 짝 → to take를 taking(갖는 것)으로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]},{"no":"12","chunks":[{"en":"Dora cannot tell","ko":"도라는 구분할 수 없다","k":"","lab":""},{"en":"if she is nervous","ko":"그녀가 긴장한 건지","k":"S","lab":"S 짝 A nervous (형용사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"excited about taking her first plane ride.","ko":"처음으로 비행기를 타는 것에 대해 흥분한 건지.","k":"V","lab":"V excited (excites 아님)"}],"tr":"Dora는 처음으로 비행기를 타는 것에 대해 그녀가 긴장한 건지 또는 흥분한 건지 구분할 수 없다.","why":"<b>is</b> 뒤의 보어 <b>nervous</b>(긴장한)는 형용사예요. or 뒤에도 형용사 역할을 하는 분사가 와야 해요. 사람이 흥분을 &ldquo;느끼는&rdquo; 쪽이라서 <b>excites → excited</b>(excite: 흥분시키다 → 흥분한)로 고쳐요. excites는 동사라서 안 돼요.","ex":"<b>cannot tell if ~</b>는 &ldquo;~인지 구분할 수 없다&rdquo;예요. 이 if는 &ldquo;~인지 아닌지&rdquo;(CH09에서 배워요). about taking ~ ride는 &ldquo;비행기를 타는 것에 대해&rdquo;.","st":[["s","짝 A","nervous (형용사)"],["c","접속사","or"],["s","짝 B","excites → excited"]],"verb":{"ok":"excited","no":"excites"},"note":{"t":"is 뒤 보어 짝은 형용사끼리","lines":["nervous ↔ excited","is 뒤 형용사 짝 → excites를 excited(흥분한)로"]},"taps":[{"k":"C","t":"연결어를 누르세요"},{"k":"S","t":"짝이 되는 앞부분을 누르세요"}]}],"cprompt":"맞는 말을 고르세요"},{"id":"c08s1","page":98,"title":"짧은 지문 연습 제대로","sub":"각 네모 안에서 어법에 맞는 표현 고르기 · 틀린 것 찾기","prompt":"연결어를 누르세요","pnote":{"t":"지문에서도 연결어 앞뒤 짝 찾기","lines":["and, or, but 앞에 있는 말의 모양을 찾아 뒤도 같은 모양으로 맞춘다","not only A but B처럼 짝이 되는 표현도 같은 모양이어야 한다"]},"items":[{"no":"1-(A)","chunks":[{"en":"Most people know that","ko":"대부분의 사람들은 ~라는 것을 안다","k":"","lab":""},{"en":"wasting all their money","ko":"모든 돈을 낭비하는 것","k":"S","lab":"S 짝 A (동명사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"(A) forgetting to save for the future","ko":"미래를 위해 저축하는 것을 잊는 것","k":"V","lab":"V forgetting (forget 아님)"},{"en":"is unwise.","ko":"이 현명하지 않다는 것을.","k":"","lab":""}],"tr":"대부분의 사람들은 모든 돈을 낭비하는 것이나 미래를 위해 저축하는 것을 잊는 것이 현명하지 않다는 것을 안다.","why":"that절의 주어 자리예요. 앞에 동명사 <b>wasting</b>(waste: 낭비하다)이 있으니 or 뒤도 동명사 <b>forgetting</b>(forget: 잊다)이 맞아요. 동사원형 forget은 주어가 될 수 없어요. 뒤의 is(be: ~이다)가 이 절의 진짜 동사예요.","ex":"<b>forget to save</b>는 &ldquo;저축하는 것을 잊다&rdquo;예요. to save for the future(미래를 위해 저축하는 것)는 forgetting의 목적어예요.","st":[["s","짝 A","wasting (동명사)"],["c","접속사","or"],["s","짝 B","forgetting (동명사)"]],"verb":{"ok":"forgetting","no":"forget"},"note":{"t":"or 앞뒤는 같은 모양으로","lines":["wasting + or + forgetting","or 앞이 동명사(wasting)이니 뒤도 동명사(forgetting)로 맞춘다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>Most people know that wasting all their money or (A) forget / forgetting to save for the future is unwise.</u> Make an effort to plan your spending carefully and (B) leave / leaving some money in the bank.","pts":["8.2","8.1"]},{"no":"1-(B)","chunks":[{"en":"Make an effort to plan your spending carefully","ko":"당신의 소비를 신중하게 계획하도록 노력하라","k":"S","lab":"S 짝 A (명령문 Make)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"(B) leave some money in the bank.","ko":"은행에 돈을 남겨두라.","k":"V","lab":"V leave (leaving 아님)"}],"tr":"당신의 소비를 신중하게 계획하도록 노력하고 은행에 돈을 남겨둬라.","why":"동사원형으로 시작하는 명령문이에요. <b>Make</b>(make: 하다)와 and로 이어진 동사도 동사원형이어야 해서 <b>leave</b>(leave: 남겨 두다)가 맞아요.","ex":"<b>make an effort to V</b>는 &ldquo;V하려고 노력하다&rdquo;예요. to plan으로 짝을 봐도 to가 생략된 leave라서 답은 같아요.","st":[["s","짝 A","Make (명령문)"],["c","접속사","and"],["s","짝 B","leave (동사원형)"]],"verb":{"ok":"leave","no":"leaving"},"note":{"t":"명령문끼리 이어지면 동사원형","lines":["Make ~ + and + leave","and 앞이 명령문(Make)이니 뒤도 동사원형 leave로 맞춘다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Most people know that wasting all their money or (A) forget / forgetting to save for the future is unwise. <u>Make an effort to plan your spending carefully and (B) leave / leaving some money in the bank.</u>","pts":["8.1"]},{"no":"2-(A)","chunks":[{"en":"It’s good to try and solve problems on your own, but you don’t always have to be","ko":"스스로 노력해서 문제를 해결하는 것은 좋지만, 당신은 항상 ~일 필요는 없다","k":"","lab":""},{"en":"alone","ko":"혼자인","k":"S","lab":"S 짝 A (형용사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"(A) isolated from others.","ko":"다른 사람들로부터 고립된.","k":"V","lab":"V isolated (isolate 아님)"}],"tr":"스스로 노력해서 문제를 해결하는 것은 좋지만, 당신은 항상 혼자이고 다른 사람들로부터 고립될 필요는 없다.","why":"<b>be</b> 뒤의 보어 <b>alone</b>(혼자인)은 형용사예요. and 뒤에도 형용사 역할을 하는 분사가 와야 해서 <b>isolated</b>(isolate: 고립시키다 → 고립된)가 맞아요. 사람이 고립을 &ldquo;당하는&rdquo; 쪽이라 -ed예요.","ex":"<b>try and solve</b>는 &ldquo;해결하려고 노력하다&rdquo;(try to solve와 같은 뜻)예요. <b>don’t have to V</b>는 &ldquo;V할 필요가 없다&rdquo;.","st":[["s","짝 A","alone (형용사)"],["c","접속사","and"],["s","짝 B","isolated (분사)"]],"verb":{"ok":"isolated","no":"isolate"},"note":{"t":"be 뒤에 이어지는 말은 같은 모양","lines":["be alone + and + isolated","be 뒤에 alone(형용사)과 isolated(과거분사, 형용사처럼 씀)가 and로 이어진다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>It’s good to try and solve problems on your own, but you don’t always have to be alone and (A) isolate / isolated from others.</u> When making a difficult decision, you can either trust your instincts or (B) get / to get advice from a friend or family member.","pts":["8.1"]},{"no":"2-(B)","chunks":[{"en":"When making a difficult decision,","ko":"어려운 결정을 내릴 때,","k":"","lab":""},{"en":"you can either trust your instincts","ko":"당신은 본능을 믿을 수 있고","k":"S","lab":"S 짝 A (조동사 뒤 동사원형)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 either ~ or"},{"en":"(B) get advice from a friend or family member.","ko":"친구나 가족 구성원에게서 조언을 얻을 수 있다.","k":"V","lab":"V get (to get 아님)"}],"tr":"어려운 결정을 내릴 때, 당신은 자신의 본능을 믿거나 친구나 가족 구성원으로부터 조언을 얻는 것 중 하나를 할 수 있다.","why":"조동사 <b>can</b> 뒤에 동사원형 <b>trust</b>(trust: 믿다)가 있어요. <b>either A or B</b>(둘 중 하나)의 B도 동사원형 <b>get</b>(get: 얻다)이 맞아요. to get은 동사가 아니라 짝이 될 수 없어요.","ex":"<b>When making a difficult decision</b>은 &ldquo;어려운 결정을 내릴 때&rdquo;예요. when 뒤에 you are가 생략된 모양이에요.","st":[["s","짝 A","trust (동사원형)"],["c","접속사","either ~ or"],["s","짝 B","get (동사원형)"]],"verb":{"ok":"get","no":"to get"},"note":{"t":"조동사 can 뒤 동사원형끼리","lines":["can trust + or + get","can 뒤에 trust가 동사원형이니 or 뒤 get도 동사원형(to get 아님)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"It’s good to try and solve problems on your own, but you don’t always have to be alone and (A) isolate / isolated from others. <u>When making a difficult decision, you can either trust your instincts or (B) get / to get advice from a friend or family member.</u>","pts":["8.1"]},{"no":"3-(A)","chunks":[{"en":"According to a study,","ko":"한 연구에 따르면,","k":"","lab":""},{"en":"people prefer using text chat to voice chat","ko":"사람들은 음성 채팅보다 문자 채팅 사용을 선호한다","k":"","lab":""},{"en":"to convey their feelings","ko":"자신의 감정을 전달하기 위해","k":"S","lab":"S 짝 A (to부정사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"(A) make requests of others.","ko":"다른 사람들에게 요청을 하기 위해.","k":"V","lab":"V make (making 아님, to 생략)"}],"tr":"한 연구에 따르면, 사람들은 자신의 감정을 전달하거나 다른 사람들에게 요청을 하기 위해 음성 채팅보다 문자 채팅을 사용하는 것을 선호한다.","why":"목적을 나타내는 to부정사 <b>to convey</b>(convey: 전달하다)가 있어요. or 뒤도 같은 to부정사가 와야 하는데 뒤쪽 to는 생략할 수 있어서 동사원형 <b>make</b>(make: (요청을) 하다)가 맞아요.","ex":"<b>prefer A to B</b>는 &ldquo;B보다 A를 선호하다&rdquo;예요. 여기서는 using text chat(A)과 voice chat(B)이에요. make requests of others = 다른 사람들에게 요청하다.","st":[["s","짝 A","to convey (to부정사)"],["c","접속사","or"],["s","짝 B","(to) make (to 생략)"]],"verb":{"ok":"make","no":"making"},"note":{"t":"to부정사끼리 이어지면 뒤 to는 생략","lines":["to convey + or + (to) make","or 앞이 to convey이니 뒤는 make(to 생략 가능). making은 안 된다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>According to a study, people prefer using text chat to voice chat to convey their feelings or (A) make / making requests of others.</u> Users say that text chat is more enjoyable, requires less effort, and (B) feel / feels more polite than voice chat.","pts":["8.2"]},{"no":"3-(B)","chunks":[{"en":"Users say that","ko":"사용자들은 ~라고 말한다","k":"","lab":""},{"en":"text chat is more enjoyable,","ko":"문자 채팅이 더 즐겁고,","k":"S","lab":"S 짝 A (단수 동사 is)"},{"en":"requires less effort,","ko":"더 적은 노력을 요구하며,","k":"S","lab":"S 짝 B (단수 동사 requires)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"(B) feels more polite than voice chat.","ko":"음성 채팅보다 더 예의 바르게 느껴진다.","k":"V","lab":"V feels (feel 아님)"}],"tr":"사용자들은 문자 채팅이 음성 채팅보다 더 즐겁고, 더 적은 노력을 요구하며, 더 예의 바르게 느껴진다고 말한다.","why":"that절의 주어 <b>text chat</b>(한 가지)에 맞춘 동사가 이어지고 있어요. <b>is</b>(be: ~이다), <b>requires</b>(require: 요구하다)가 단수동사이니 세 번째도 단수동사 <b>feels</b>(feel: 느껴지다)가 맞아요.","ex":"<b>more enjoyable / less effort / more polite than ~</b>는 &ldquo;~보다 더 즐거운 / 더 적은 노력 / 더 예의 바른&rdquo;처럼 비교하는 말이에요.","st":[["s","짝 A","is (단수동사)"],["s","짝 B","requires (단수동사)"],["c","접속사","and"],["s","짝 C","feels (단수동사)"]],"verb":{"ok":"feels","no":"feel"},"note":{"t":"같은 주어의 동사끼리 병렬","lines":["is + requires + and + feels","주어 text chat(단수)에 맞춰 is, requires, feels 모두 단수 동사"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"According to a study, people prefer using text chat to voice chat to convey their feelings or (A) make / making requests of others. <u>Users say that text chat is more enjoyable, requires less effort, and (B) feel / feels more polite than voice chat.</u>","pts":["8.1"]},{"no":"4-①","chunks":[{"en":"By emitting light, some sea creatures make themselves visible","ko":"빛을 내뿜음으로써, 어떤 바다 생물들은 자신들을 보이게 만든다","k":"","lab":""},{"en":"to attract prey","ko":"먹이를 유인하기 위해","k":"S","lab":"S 짝 A (to부정사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"to find mates.","ko":"짝을 찾기 위해.","k":"V","lab":"V to find (이미 맞음)"}],"tr":"빛을 내뿜음으로써, 어떤 바다 생물들은 먹이를 유인하거나 짝을 찾기 위해 그들 자신을 보이게 만든다.","why":"목적을 나타내는 to부정사 <b>to attract</b>(attract: 유인하다)와 or로 이어진 <b>to find</b>(find: 찾다)는 같은 to부정사라서 맞아요.","ex":"<b>By emitting light</b>는 &ldquo;빛을 내뿜음으로써&rdquo;예요. <b>make A visible</b>은 &ldquo;A를 보이게 만들다&rdquo;.","st":[["s","짝 A","to attract (to부정사)"],["c","접속사","or"],["s","짝 B","to find (to부정사, 맞음)"]],"verb":{"ok":"to find","no":"finding"},"note":{"t":"to부정사끼리 이어지기","lines":["to attract + or + to find","or 앞이 to attract이니 뒤도 to find(이미 맞음)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>By emitting light, some sea creatures make themselves visible to attract prey or ① to find mates.</u> However, other sea creatures do not reveal themselves but ② hiding by using light to make themselves difficult to see.","pts":["8.2"]},{"no":"4-②","chunks":[{"en":"However, other sea creatures do not reveal themselves","ko":"하지만, 다른 바다 생물들은 자신들을 드러내지 않고","k":"S","lab":"S 짝 A (not 뒤 동사원형 reveal)"},{"en":"but","ko":"오히려","k":"C","lab":"C 연결어 not ~ but"},{"en":"hide by using light","ko":"빛을 이용해서 숨는다","k":"V","lab":"V hide (hiding을 고침)"},{"en":"to make themselves difficult to see.","ko":"자신들을 보기 어렵게 만들기 위해.","k":"","lab":""}],"tr":"하지만, 다른 바다 생물들은 자신들을 드러내지 않고 자신들을 보기 어렵게 하기 위해 빛을 이용해서 숨는다.","why":"<b>do not reveal</b>에서 not 뒤에는 동사원형 <b>reveal</b>(reveal: 드러내다)이 와요. not A but B의 B도 같은 동사원형이어야 해서 <b>hiding → hide</b>(hide: 숨다)로 고쳐요.","ex":"<b>by using light to make themselves difficult to see</b>는 &ldquo;빛을 이용해서 자신을 보기 어렵게 만들어서&rdquo;(방법)예요. 이 using은 병렬과 상관없어요.","st":[["s","짝 A","reveal (동사원형)"],["c","접속사","not ~ but"],["s","짝 B","hiding → hide"]],"verb":{"ok":"hide","no":"hiding"},"note":{"t":"not A but B는 같은 모양","lines":["not reveal + but + hide","do not 뒤 reveal이 동사원형이니 but 뒤도 hide(hiding을 고침)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"By emitting light, some sea creatures make themselves visible to attract prey or ① to find mates. <u>However, other sea creatures do not reveal themselves but ② hiding by using light to make themselves difficult to see.</u>","pts":["8.1","8.2"]},{"no":"5-①","chunks":[{"en":"Doing volunteer work provides chances","ko":"봉사활동을 하는 것은 기회들을 제공한다","k":"","lab":""},{"en":"to help the community,","ko":"공동체를 돕는","k":"S","lab":"S 짝 A (to부정사)"},{"en":"meet various people,","ko":"다양한 사람들을 만나는","k":"S","lab":"S 짝 B (to 생략)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"experience positive emotions.","ko":"긍정적인 감정을 경험하는.","k":"V","lab":"V experience (experiencing 아님, to 생략)"}],"tr":"봉사활동을 하는 것은 공동체를 돕고, 다양한 사람들을 만나고, 긍정적인 감정을 경험하는 기회를 제공한다.","why":"chances(기회들)를 꾸미는 to부정사 <b>to help</b>(help: 돕다) 뒤에, to가 생략된 <b>meet</b>(meet: 만나다), <b>experience</b>(experience: 경험하다)가 이어졌어요. 같은 모양이라서 맞아요.","ex":"<b>Doing volunteer work</b>(봉사활동을 하는 것)는 동명사 주어라서 단수동사 provides가 왔어요(CH01).","st":[["s","짝 A","to help"],["s","짝 B","(to) meet (to 생략)"],["c","접속사","and"],["s","짝 C","(to) experience (to 생략, 맞음)"]],"verb":{"ok":"experience","no":"experiencing"},"note":{"t":"to부정사가 셋 이어지면 뒤 to는 생략","lines":["to help + meet + (to) experience","첫 to만 쓰고 뒤는 동사원형. experience는 이미 맞다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>Doing volunteer work provides chances to help the community, meet various people, and ① experience positive emotions.</u> In addition, it is helpful for both promoting personal growth and ② develops useful skills in many areas of life.","pts":["8.2"]},{"no":"5-②","chunks":[{"en":"In addition, it is helpful for both","ko":"게다가, 그것은 둘 다에 도움이 된다","k":"","lab":""},{"en":"promoting personal growth","ko":"개인적인 성장을 촉진하는 것","k":"S","lab":"S 짝 A (동명사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 both ~ and"},{"en":"developing useful skills in many areas of life.","ko":"삶의 많은 영역에서 유용한 기술을 개발하는 것.","k":"V","lab":"V developing (develops를 고침)"}],"tr":"게다가, 그것은 개인적인 성장을 촉진하는 것과 삶의 많은 부분에서 유용한 기술을 개발하는 것 둘 다에 도움이 된다.","why":"<b>for</b>는 전치사라서 뒤에 동명사가 와요. <b>both A and B</b>에서 A가 동명사 <b>promoting</b>(promote: 촉진하다)이니까 B도 동명사로 맞춰야 해서 <b>develops → developing</b>(develop: 개발하다)으로 고쳐요.","ex":"<b>In addition,</b>은 &ldquo;게다가&rdquo;라는 이어 주는 말이에요. be helpful for ~ = ~에 도움이 되다.","st":[["s","짝 A","promoting (동명사)"],["c","접속사","both ~ and"],["s","짝 B","develops → developing"]],"verb":{"ok":"developing","no":"develops"},"note":{"t":"전치사 뒤 동명사끼리 병렬","lines":["promoting + and + developing","for(전치사) 뒤라 promoting이 동명사. 뒤도 developing(develops를 고침)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Doing volunteer work provides chances to help the community, meet various people, and ① experience positive emotions. <u>In addition, it is helpful for both promoting personal growth and ② develops useful skills in many areas of life.</u>","pts":["8.2"]},{"no":"6-1","chunks":[{"en":"Jerry,","ko":"제리는","k":"S","lab":"S 주어(단수)"},{"en":"who is a teacher,","ko":"선생님인","k":"M","lab":"관계절 수식어"},{"en":"once received a letter from a student.","ko":"한 학생으로부터 편지를 한 통 받은 적이 있다.","k":"V","lab":"V received (이미 맞음)"}],"tr":"선생님인 Jerry는 한 학생으로부터 편지를 한 통 받은 적이 있다.","why":"","ex":"","st":[],"verb":{"ok":"received","no":"receive"},"note":{"t":"이야기 시작: 주어의 과거 동사","lines":["Jerry (who is a teacher) + received","관계절은 건너뛰고 주어 Jerry의 동사 received(원형 receive 받다)를 본다"]},"taps":[{"k":"S","t":"주어를 누르세요"},{"k":"M","t":"건너뛸 꾸밈말을 누르세요"}],"ctx":"<u>Jerry, who is a teacher, once received a letter from a student.</u> It consisted of 14 ① unrelated and lengthy questions on a variety of subjects. The teacher wrote back a long reply, and soon received a return letter. In the letter, the student not only noted his forgetting one question, but ② expressing no thanks for the effort he made."},{"no":"6-①","chunks":[{"en":"It consisted of","ko":"그것은 구성되었다","k":"V","lab":"V consisted (이미 맞음)"},{"en":"14 unrelated","ko":"14개의 서로 관련이 없는","k":"S","lab":"S 짝 A (분사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"lengthy","ko":"긴","k":"S","lab":"S 짝 B (형용사)"},{"en":"questions on a variety of subjects.","ko":"다양한 주제에 대한 질문들로.","k":"","lab":""}],"tr":"그것은 다양한 주제에 대한 14개의 서로 관련이 없고 긴 질문들로 구성되었다.","why":"and 뒤의 <b>lengthy</b>(긴)는 questions(질문들)를 꾸미는 형용사예요. 앞의 <b>unrelated</b>(관련 없는)도 questions를 꾸미는 분사 모양의 말이라서 맞아요.","ex":"<b>consist of ~</b>는 &ldquo;~로 구성되다&rdquo;, <b>a variety of ~</b>는 &ldquo;다양한 ~&rdquo;이에요.","st":[["s","짝 A","unrelated (분사)"],["c","접속사","and"],["s","짝 B","lengthy (형용사)"]],"verb":{"ok":"consisted","no":"consists"},"note":{"t":"명사 앞 꾸미는 말끼리 병렬","lines":["unrelated + and + lengthy","and로 이어진 두 말이 모두 뒤 questions를 꾸민다(이미 맞음)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Jerry, who is a teacher, once received a letter from a student. <u>It consisted of 14 ① unrelated and lengthy questions on a variety of subjects.</u> The teacher wrote back a long reply, and soon received a return letter. In the letter, the student not only noted his forgetting one question, but ② expressing no thanks for the effort he made.","pts":["8.3"]},{"no":"6-3","chunks":[{"en":"The teacher","ko":"선생님은","k":"S","lab":"S 주어"},{"en":"wrote back a long reply,","ko":"긴 답장을 써서 보냈고,","k":"V","lab":"V wrote (이미 맞음)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"soon received a return letter.","ko":"곧 답장을 받았다.","k":"V","lab":"V received (receives 아님)"}],"tr":"선생님은 긴 답장을 써서 보냈고, 곧 답장을 받았다.","why":"","ex":"","st":[],"verb":{"ok":"received","no":"receives"},"note":{"t":"and로 이어진 동사는 같은 시제","lines":["wrote + and + received","wrote(원형 write 쓰다)가 과거이니 뒤도 received(원형 receive 받다)"]},"taps":[{"k":"C","t":"연결어를 누르세요"}],"ctx":"Jerry, who is a teacher, once received a letter from a student. It consisted of 14 ① unrelated and lengthy questions on a variety of subjects. <u>The teacher wrote back a long reply, and soon received a return letter.</u> In the letter, the student not only noted his forgetting one question, but ② expressing no thanks for the effort he made."},{"no":"6-②","chunks":[{"en":"In the letter, the student not only noted his forgetting one question,","ko":"편지에서, 그 학생은 그가 하나의 질문을 잊은 것을 언급했을 뿐만 아니라,","k":"S","lab":"S 짝 A (과거 noted)"},{"en":"but","ko":"또한","k":"C","lab":"C 연결어 not only ~ but"},{"en":"expressed no thanks for the effort he made.","ko":"그가 한 노력에 대해 감사를 표현하지도 않았다.","k":"V","lab":"V expressed (expressing을 고침)"}],"tr":"편지에서, 그 학생은 그가 하나의 질문을 잊은 것을 언급했을 뿐만 아니라, 그가 한 노력에 대해 감사를 표현하지도 않았다.","why":"<b>not only A but (also) B</b>에서 A는 과거 동사 <b>noted</b>(note: 언급하다)예요. 그래서 B도 과거 동사여야 해서 <b>expressing → expressed</b>(express: 표현하다)로 고쳐요.","ex":"<b>his forgetting one question</b>은 &ldquo;그가 질문 하나를 잊은 것&rdquo;이에요. 동명사 forgetting(forget: 잊다) 앞의 his는 &ldquo;누가 잊었는지&rdquo;를 알려 줘요.","st":[["s","짝 A","noted (과거)"],["c","접속사","not only ~ but"],["s","짝 B","expressing → expressed (과거)"]],"verb":{"ok":"expressed","no":"expressing"},"note":{"t":"not only A but B는 같은 시제","lines":["noted + but + expressed","noted(원형 note 언급하다)가 과거이니 뒤도 과거 expressed(원형 express 표현하다)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Jerry, who is a teacher, once received a letter from a student. It consisted of 14 ① unrelated and lengthy questions on a variety of subjects. The teacher wrote back a long reply, and soon received a return letter. <u>In the letter, the student not only noted his forgetting one question, but ② expressing no thanks for the effort he made.</u>","pts":["8.1"]}],"cprompt":"알맞은 표현을 고르세요"},{"id":"c08s2","page":99,"title":"내신 서술형 대비 제대로","sub":"괄호 단어를 알맞게 쓰기 · 순서 배열 · 틀린 곳 고쳐 쓰기","prompt":"연결어를 누르세요","pnote":{"t":"쓰는 문제도 앞의 짝부터","lines":["연결어 앞의 말이 동사, 동명사, to부정사, 분사 중 무엇인지 먼저 본다","뒤에 오는 말도 같은 모양으로 쓰고, 동사는 시제와 수까지 맞춘다"]},"items":[{"no":"1","chunks":[{"en":"I will go to the department store","ko":"나는 백화점에 갈 것이다","k":"","lab":""},{"en":"both","ko":"둘 다","k":"C","lab":"C 연결어 both ~ and"},{"en":"to go shopping","ko":"쇼핑하기 위해","k":"S","lab":"S 짝 A (to부정사)"},{"en":"and (to) have lunch.","ko":"그리고 점심을 먹기 위해.","k":"V","lab":"V (to) have (원형 have 먹다)","h":[["and","c"],["have","v"]]}],"tr":"나는 쇼핑하고 점심 먹는 것 둘 다 하기 위해 백화점을 방문할 것이다.","why":"<b>both A and B</b>에서 A가 to부정사 <b>to go</b>(go: 가다)예요. B도 to부정사여야 하는데, 뒤쪽 to는 생략할 수 있어서 <b>(to) have</b>(have: 먹다)가 맞아요. 보기 중 have를 골라요.","ex":"<b>go shopping</b>은 &ldquo;쇼핑하러 가다&rdquo;예요. have lunch = 점심을 먹다.","st":[["s","짝 A","to go (to부정사)"],["c","접속사","both ~ and"],["s","짝 B","(to) have (to 생략 가능)"]],"verb":{"ok":"have","no":"having"},"note":{"t":"빈칸에 쓸 말: (to) have","lines":["both to go + and + (to) have","to부정사끼리 이어지니 have(원형, 먹다). to는 생략해도 된다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"I will go to the department store both to go shopping and ___ lunch.","kor":"나는 쇼핑하고 점심 먹는 것 둘 다 하기 위해 백화점을 방문할 것이다. (보기: damage, forget, have)","pts":["8.2"]},{"no":"2","chunks":[{"en":"She is usually very good at cooking,","ko":"그녀는 보통은 요리를 매우 잘하지만,","k":"S","lab":"S 짝 A (단수 동사 is)"},{"en":"but","ko":"하지만","k":"C","lab":"C 연결어 but"},{"en":"sometimes forgets to add salt.","ko":"가끔 소금을 넣는 것을 잊는다.","k":"V","lab":"V forgets (forget 아님)"}],"tr":"그녀는 보통은 요리를 매우 잘하지만, 가끔 소금을 넣는 것을 잊는다.","why":"앞의 동사 <b>is</b>(be: ~이다)가 주어 She(한 명)의 단수동사예요. but 뒤의 동사도 같은 주어의 단수동사여야 해서 보기의 forget을 <b>forgets</b>(forget: 잊다)로 바꿔요.","ex":"<b>forget to V</b>는 &ldquo;V할 것을 잊다&rdquo;(해야 할 일을 깜빡하다)예요. be good at ~ = ~을 잘하다.","st":[["s","짝 A","is (단수동사)"],["c","접속사","but"],["s","짝 B","forgets (단수동사)"]],"verb":{"ok":"forgets","no":"forget"},"note":{"t":"빈칸에 쓸 말: forgets","lines":["is + but + forgets","주어 She(단수)와 앞 동사 is에 맞춰 forget을 forgets(원형 forget 잊다)로 쓴다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"She is usually very good at cooking, but sometimes ___ to add salt.","kor":"그녀는 보통은 요리를 매우 잘하지만, 가끔 소금을 넣는 것을 잊는다. (보기: damage, forget, have)","pts":["8.1"]},{"no":"3","chunks":[{"en":"Athletes have more problems with","ko":"운동선수들은 ~로 인해 더 많은 문제를 겪는다","k":"","lab":""},{"en":"damaged","ko":"손상된","k":"V","lab":"V damaged (damage의 분사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"painful","ko":"아픈","k":"S","lab":"S 짝 B (형용사)"},{"en":"joints than ordinary people.","ko":"관절들로, 보통 사람들보다.","k":"","lab":""}],"tr":"운동선수들은 보통 사람들보다 손상되거나 아픈 관절로 인해 더 많은 문제를 겪는다.","why":"or 뒤의 <b>painful</b>(아픈)은 joints(관절)를 꾸미는 형용사예요. 앞도 joints를 꾸미는 분사여야 해요. 관절이 &ldquo;손상된&rdquo; 쪽이라서 보기의 damage를 과거분사 <b>damaged</b>(damage: 손상시키다 → 손상된)로 바꿔요.","ex":"<b>more problems than ~</b>는 &ldquo;~보다 더 많은 문제&rdquo;예요. ordinary people = 보통 사람들.","st":[["s","짝 A","damaged (분사)"],["c","접속사","or"],["s","짝 B","painful (형용사)"]],"verb":{"ok":"damaged","no":"damaging"},"note":{"t":"빈칸에 쓸 말: damaged","lines":["damaged + or + painful","뒤의 painful(아픈)처럼 joints(관절들)를 꾸미는 말. damage(손상시키다)는 damaged(손상된)"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Athletes have more problems with ___ or painful joints than ordinary people.","kor":"운동선수들은 보통 사람들보다 손상되거나 아픈 관절로 인해 더 많은 문제를 겪는다. (보기: damage, forget, have)","pts":["8.3"]},{"no":"4","chunks":[{"en":"Check your bags","ko":"당신의 가방을 확인하라","k":"S","lab":"S 짝 A (명령문)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"place the printed tickets","ko":"인쇄된 항공권을 두라","k":"V","lab":"V place (placing 아님)"},{"en":"somewhere safe","ko":"안전한 어딘가에","k":"","lab":""},{"en":"before leaving for the airport.","ko":"공항으로 떠나기 전에.","k":"","lab":""}],"tr":"공항으로 떠나기 전에 당신의 가방을 확인하고 인쇄된 항공권을 안전한 어딘가에 두세요.","why":"&ldquo;~해라&rdquo;(명령문) 두 개를 and로 이었어요. 동사원형 <b>Check</b>(check: 확인하다)와 <b>place</b>(place: 두다)를 짝지어요. 인쇄된 항공권은 the printed tickets로 써요.","ex":"<b>printed</b>(print: 인쇄하다 → 인쇄된)는 tickets를 꾸미는 과거분사예요. before leaving for the airport = 공항으로 떠나기 전에.","st":[["s","짝 A","Check your bags (명령문)"],["c","접속사","and"],["s","짝 B","place the printed tickets (명령문)"]],"verb":{"ok":"place","no":"placing"},"note":{"t":"배열: 명령문 and 명령문","lines":["Check your bags and place the printed tickets","and 앞뒤 모두 동사원형으로 시작하는 명령문"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"___ somewhere safe before leaving for the airport.","kor":"공항으로 떠나기 전에 당신의 가방을 확인하고 인쇄된 항공권을 안전한 어딘가에 두세요. (and, check, place, the printed tickets, your bags)","pts":["8.1"],"order":{"pool":["your bags","check","place","the printed tickets","and"],"seq":["check","your bags","and","place","the printed tickets"]}},{"no":"5","chunks":[{"en":"She was not unhappy","ko":"그녀는 불쾌한 것이 아니라","k":"S","lab":"S 짝 A (형용사)"},{"en":"but","ko":"오히려","k":"C","lab":"C 연결어 not ~ but"},{"en":"surprised","ko":"놀랐다","k":"V","lab":"V surprised (surprise를 고침)"},{"en":"a little by the unexpected guests.","ko":"예상치 못한 손님들 때문에 약간.","k":"","lab":""}],"tr":"그녀는 불쾌한 것이 아니라 예상치 못한 손님들 때문에 약간 놀랐다.","why":"<b>not A but B</b>(A가 아니라 B)를 was 뒤 보어 자리에 써요. A는 형용사 <b>unhappy</b>(불쾌한), B는 분사 <b>surprised</b>(surprise: 놀라게 하다 → 놀란)예요. 사람이 놀람을 &ldquo;느끼는&rdquo; 쪽이라 -ed예요.","ex":"<b>was surprised by ~</b>는 &ldquo;~ 때문에 놀랐다&rdquo;(수동)예요. a little = 약간. unexpected = 예상치 못한.","st":[["s","주어","She"],["v","동사","was"],["s","짝 A","not unhappy"],["c","접속사","but"],["s","짝 B","surprised"]],"verb":{"ok":"surprised","no":"surprising"},"note":{"t":"배열: not A but B","lines":["She was not unhappy but surprised","not unhappy와 짝이 되도록 surprise를 surprised로 쓴다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"___ a little by the unexpected guests.","kor":"그녀는 불쾌한 것이 아니라 예상치 못한 손님들 때문에 약간 놀랐다. (but, not, she, surprise, unhappy, was)","pts":["8.1"],"order":{"pool":["she","not","surprise","was","unhappy","but"],"seq":["she","was","not","unhappy","but","surprise"],"fix":"surprise(놀라게 하다)는 수동의 뜻이라 <b>surprised</b>(놀란)로 바꿔 써요."}},{"no":"6","chunks":[{"en":"Some people enjoy the habits of","ko":"어떤 사람들은 습관을 즐긴다","k":"","lab":""},{"en":"reading,","ko":"책을 읽는","k":"S","lab":"S 짝 A (동명사)"},{"en":"drawing,","ko":"그림을 그리는","k":"S","lab":"S 짝 B (동명사)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"growing plants","ko":"식물을 기르는","k":"V","lab":"V growing (grow 아님)"},{"en":"in their spare time to relax.","ko":"여가 시간에 긴장을 풀기 위해.","k":"","lab":""}],"tr":"어떤 사람들은 긴장을 풀기 위해 여가 시간에 책을 읽거나, 그림을 그리거나, 식물을 기르는 습관을 즐긴다.","why":"<b>of</b>는 전치사라서 뒤에 동명사가 와요. <b>reading</b>(read: 읽다), <b>drawing</b>(draw: 그리다), <b>growing</b>(grow: 기르다)을 콤마와 or로 이어 세 개를 나열해요.","ex":"<b>in their spare time</b>(여가 시간에)은 맨 끝 덩어리 뒤에 붙는 꾸밈말이에요. <b>to relax</b>는 &ldquo;긴장을 풀기 위해&rdquo;(목적).","st":[["s","짝 A","reading"],["s","짝 B","drawing"],["c","접속사","or"],["s","짝 C","growing plants"]],"verb":{"ok":"growing","no":"grow"},"note":{"t":"배열: 동명사 A, B, or C","lines":["reading, drawing, or growing plants","of(전치사) 뒤 동명사끼리 이어지니 read, draw, grow를 모두 -ing로"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Some people enjoy the habits of ___ to relax.","kor":"어떤 사람들은 긴장을 풀기 위해 여가 시간에 책을 읽거나, 그림을 그리거나, 식물을 기르는 습관을 즐긴다. (draw, grow plants, in, or, read, their spare time)","pts":["8.2"],"order":{"pool":["draw","in","their spare time","read","grow plants","or"],"seq":["read","draw","or","grow plants","in","their spare time"],"fix":"read, draw, grow plants는 앞뒤를 맞추어 <b>reading, drawing, growing plants</b>처럼 동명사로 써요."}},{"no":"7-1","chunks":[{"en":"“We sit at a table","ko":"“우리는 식탁에 앉는다","k":"","lab":""},{"en":"not only","ko":"~ 뿐만 아니라","k":"C","lab":"C 연결어 not only ~ but"},{"en":"to eat","ko":"먹기 위해","k":"S","lab":"S 짝 A (to부정사)"},{"en":"but","ko":"또한","k":"C","lab":"C 연결어 but"},{"en":"to connect together,”","ko":"함께 연결하기 위해서도,”","k":"V","lab":"V to connect (이미 맞음)"},{"en":"said the Greek author Plutarch.","ko":"그리스 작가 플루타르코스가 말했다.","k":"","lab":""}],"tr":"그리스 작가 Plutarch는 “우리는 먹기 위해 뿐만 아니라 함께 연결하기 위해 식탁에 앉는다”고 말했다.","why":"ⓐ <b>not only A but (also) B</b>에서 A가 to부정사 <b>to eat</b>(eat: 먹다)예요. B도 to부정사 <b>to connect</b>(connect: 연결하다)라서 맞아요.","ex":"<b>said the Greek author Plutarch</b>는 &ldquo;그리스 작가 Plutarch가 말했다&rdquo;예요. said는 say(말하다)의 과거형.","st":[["s","짝 A","to eat (to부정사)"],["c","접속사","not only ~ but"],["s","짝 B","to connect (to부정사, 맞음)"]],"verb":{"ok":"to connect","no":"connecting"},"note":{"t":"not only A but B는 같은 모양","lines":["to eat + but + to connect","A가 to eat(먹다)이니 B도 to connect(연결하다). 이미 맞다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>“We sit at a table not only to eat but ⓐ to connect together,” said the Greek author Plutarch.</u> Dining is a sign of human community and ⓑ distinguishing men from beasts. Animals eat to survive but ⓒ to care nothing about the thoughts of other creatures.","pts":["8.2"]},{"no":"7-2","chunks":[{"en":"Dining is a sign of human community","ko":"식사는 인간 공동체의 표시이다","k":"S","lab":"S 짝 A (단수 동사 is)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"distinguishes men from beasts.","ko":"인간과 짐승을 구분한다.","k":"V","lab":"V distinguishes (distinguishing을 고침)"}],"tr":"식사는 인간 공동체의 표시이고 인간과 짐승을 구분한다.","why":"ⓑ 주어 <b>Dining</b>(식사하는 것)의 동사 <b>is</b>(be: ~이다)와 and로 이어지는 자리라서 동사가 와야 해요. 주어가 하나(단수)라서 <b>distinguishing → distinguishes</b>(distinguish: 구분하다)로 고쳐요.","ex":"<b>a sign of ~</b>는 &ldquo;~의 표시&rdquo;, <b>distinguish A from B</b>는 &ldquo;A와 B를 구분하다&rdquo;예요. beast: 짐승.","st":[["s","짝 A","is (단수동사)"],["c","접속사","and"],["s","짝 B","distinguishing → distinguishes"]],"verb":{"ok":"distinguishes","no":"distinguishing"},"note":{"t":"and 뒤 동사도 같은 모양","lines":["is + and + distinguishes","앞 동사 is(단수)처럼 distinguishing(원형 distinguish 구분하다)을 distinguishes로"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"“We sit at a table not only to eat but ⓐ to connect together,” said the Greek author Plutarch. <u>Dining is a sign of human community and ⓑ distinguishing men from beasts.</u> Animals eat to survive but ⓒ to care nothing about the thoughts of other creatures.","pts":["8.1"]},{"no":"7-3","chunks":[{"en":"Animals eat to survive","ko":"동물들은 살아남기 위해 먹는다","k":"S","lab":"S 짝 A (복수 동사 eat)"},{"en":"but","ko":"하지만","k":"C","lab":"C 연결어 but"},{"en":"care nothing about the thoughts of other creatures.","ko":"다른 생물들의 생각에 대해 아무것도 신경 쓰지 않는다.","k":"V","lab":"V care (to care를 고침)"}],"tr":"동물들은 살아남기 위해 먹는 것이지 다른 생물들의 생각에 대해 아무것도 신경 쓰지 않는다.","why":"ⓒ 주어 <b>Animals</b>(복수)의 동사 <b>eat</b>(eat: 먹다)와 but으로 이어지는 자리라서 동사가 와야 해요. <b>to care → care</b>(care: 신경 쓰다)로 고쳐요.","ex":"<b>to survive</b>(살아남기 위해)는 목적을 나타내는 to부정사예요. 이 to survive를 보고 to care를 짝이라고 착각하지 않도록 주의해요. care about ~ = ~에 대해 신경 쓰다.","st":[["s","짝 A","eat (복수 동사)"],["c","접속사","but"],["s","짝 B","to care → care (복수 동사)"]],"verb":{"ok":"care","no":"to care"},"note":{"t":"but 뒤 동사도 같은 모양","lines":["eat + but + care","앞 동사 eat이 복수 동사이니 to care를 care(원형, 신경 쓰다)로 고친다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"“We sit at a table not only to eat but ⓐ to connect together,” said the Greek author Plutarch. Dining is a sign of human community and ⓑ distinguishing men from beasts. <u>Animals eat to survive but ⓒ to care nothing about the thoughts of other creatures.</u>","pts":["8.1"]},{"no":"8-1","chunks":[{"en":"Can your life either get worse","ko":"당신의 삶이 더 나빠지거나","k":"S","lab":"S 짝 A (동사원형 get)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 either ~ or"},{"en":"become better","ko":"더 좋아질 수 있을까","k":"V","lab":"V become (becoming을 고침)"},{"en":"just because of the thoughts you have?","ko":"단지 당신이 가진 생각들 때문에?","k":"","lab":""}],"tr":"단지 당신이 가진 생각들 때문에 당신의 삶이 더 나빠지거나 더 좋아질 수 있을까?","why":"ⓐ 조동사 <b>Can</b> 뒤에 동사원형 <b>get</b>(get: ~해지다)이 있어요. <b>either A or B</b>의 B도 동사원형이어야 해서 <b>becoming → become</b>(become: ~이 되다)으로 고쳐요.","ex":"<b>because of ~</b>는 &ldquo;~ 때문에&rdquo;예요(CH09). the thoughts you have = 당신이 가진 생각들.","st":[["s","짝 A","get (동사원형)"],["c","접속사","either ~ or"],["s","짝 B","becoming → become"]],"verb":{"ok":"become","no":"becoming"},"note":{"t":"either A or B는 같은 모양","lines":["get + or + become","Can 뒤라 get이 동사원형. becoming을 become(원형, 되다)으로 고친다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"<u>Can your life either get worse or ⓐ becoming better just because of the thoughts you have?</u> One researcher decided to gather people having positive expectations for their success and ⓑ track their lives. Later, these individuals actually found jobs, passed their exams, or successfully ⓒ to recover from illness.","pts":["8.1"]},{"no":"8-2","chunks":[{"en":"One researcher decided","ko":"한 연구원은 결정했다","k":"","lab":""},{"en":"to gather people having positive expectations for their success","ko":"성공에 대해 긍정적인 기대를 가지고 있는 사람들을 모으기로","k":"S","lab":"S 짝 A (to부정사)"},{"en":"and","ko":"그리고","k":"C","lab":"C 연결어 and"},{"en":"track their lives.","ko":"그들의 삶을 추적하기로.","k":"V","lab":"V track (이미 맞음, to 생략)"}],"tr":"한 연구원은 성공에 대해 긍정적인 기대를 가지고 있는 사람들을 모으고 그들의 삶을 추적하기로 결정했다.","why":"ⓑ <b>decided</b>(decide: 결정하다)의 목적어인 to부정사 <b>to gather</b>(gather: 모으다)가 있어요. 이어지는 to부정사는 to를 생략할 수 있어서 동사원형 <b>track</b>(track: 추적하다)은 맞아요.","ex":"<b>people having positive expectations</b>의 having은 people을 꾸미는 분사(&ldquo;긍정적인 기대를 가지고 있는&rdquo;)예요.","st":[["s","짝 A","to gather (to부정사)"],["c","접속사","and"],["s","짝 B","(to) track (to 생략, 맞음)"]],"verb":{"ok":"track","no":"tracking"},"note":{"t":"to부정사끼리 이어지면 뒤 to는 생략","lines":["to gather + and + (to) track","to gather(모으다) 뒤 and로 이어졌으니 track(추적하다)은 이미 맞다"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Can your life either get worse or ⓐ becoming better just because of the thoughts you have? <u>One researcher decided to gather people having positive expectations for their success and ⓑ track their lives.</u> Later, these individuals actually found jobs, passed their exams, or successfully ⓒ to recover from illness.","pts":["8.2"]},{"no":"8-3","chunks":[{"en":"Later, these individuals actually found jobs,","ko":"나중에, 이 사람들은 실제로 직장을 구했고,","k":"S","lab":"S 짝 A (과거 found)"},{"en":"passed their exams,","ko":"시험을 통과했고,","k":"S","lab":"S 짝 B (과거 passed)"},{"en":"or","ko":"또는","k":"C","lab":"C 연결어 or"},{"en":"successfully recovered from illness.","ko":"성공적으로 질병에서 회복했다.","k":"V","lab":"V recovered (to recover를 고침)"}],"tr":"나중에, 이 사람들은 실제로 직장을 구하거나, 시험을 통과하거나, 또는 질병에서 성공적으로 회복했다.","why":"ⓒ <b>found</b>(find: 찾다), <b>passed</b>(pass: 통과하다)가 과거 동사로 나열돼 있어요. 세 번째도 과거 동사여야 해서 <b>to recover → recovered</b>(recover: 회복하다)로 고쳐요.","ex":"<b>successfully</b>(성공적으로)는 recovered를 꾸미는 부사예요. recover from ~ = ~에서 회복하다.","st":[["s","짝 A","found (과거)"],["s","짝 B","passed (과거)"],["c","접속사","or"],["s","짝 C","to recover → recovered (과거)"]],"verb":{"ok":"recovered","no":"to recover"},"note":{"t":"A, B, or C는 같은 시제","lines":["found + passed + or + recovered","found(원형 find 찾다), passed(원형 pass 통과하다)가 과거이니 to recover를 recovered로"]},"taps":[{"k":"S","t":"짝이 되는 앞말을 누르세요"},{"k":"C","t":"연결어를 누르세요"}],"ctx":"Can your life either get worse or ⓐ becoming better just because of the thoughts you have? One researcher decided to gather people having positive expectations for their success and ⓑ track their lives. <u>Later, these individuals actually found jobs, passed their exams, or successfully ⓒ to recover from illness.</u>","pts":["8.1"]}],"cprompt":"알맞은 표현을 고르세요"}];